    def _sales_decimal(raw: Any) -> Decimal:
        value = re.sub(r"\s+", "", str(raw or "").strip()).replace(",", ".")
        if not value:
            return Decimal("0")
        try:
            return Decimal(value)
        except Exception:
            return Decimal("0")

    def _sales_decimal_strict(raw: Any, field_label: str) -> Decimal:
        raw_text = str(raw or "").strip()
        if not raw_text:
            return Decimal("0")
        value = re.sub(r"\s+", "", raw_text).replace(",", ".")
        if not re.fullmatch(r"-?\d+(?:\.\d+)?", value):
            raise ValueError(f"{field_label}: введите число")
        try:
            return Decimal(value)
        except Exception as exc:
            raise ValueError(f"{field_label}: введите число") from exc

    def _sales_money_label(raw: Any) -> str:
        amount = _sales_decimal(raw)
        if amount == amount.to_integral():
            return f"{int(amount):,}".replace(",", " ")
        return f"{amount:,.2f}".replace(",", " ").rstrip("0").rstrip(".")

    _SALES_WORKFLOW_VERSION = 2
    _SALES_WORKFLOW_STATUSES = {
        "new": "Новый",
        "shipped": "Отгружен",
        "installation": "Установка",
        "completed": "Завершен",
        "archived": "Архив",
    }

    def _sales_workflow_status(data: dict[str, Any]) -> str:
        doc_type = str(data.get("doc_type") or "sale").strip()
        raw_status = str(data.get("status") or "new").strip().lower()
        if doc_type == "return":
            return "return"
        if int(_sales_decimal(data.get("workflow_version"))) >= _SALES_WORKFLOW_VERSION:
            return raw_status if raw_status in _SALES_WORKFLOW_STATUSES else "new"
        if doc_type == "order":
            return "new"
        return {
            "new": "shipped",
            "reserved": "shipped",
            "partial": "installation",
            "debt": "installation",
            "paid": "archived",
        }.get(raw_status, raw_status if raw_status in _SALES_WORKFLOW_STATUSES else "new")

    def _sales_status_label(status: str) -> str:
        if status == "return":
            return "Возврат"
        return _SALES_WORKFLOW_STATUSES.get(status or "", "Новый")

    def _sales_status_requires_inventory(status: str, doc_type: str) -> bool:
        if doc_type == "return":
            return True
        return status in {"shipped", "installation", "completed", "archived"}

    def _sales_status_records_debt(status: str, doc_type: str) -> bool:
        if doc_type == "return":
            return True
        return status in {"installation", "completed", "archived"}

    def _sales_status_records_profit(status: str, doc_type: str) -> bool:
        return doc_type == "return" or status == "archived"

    def _sales_inventory_applied(data: dict[str, Any]) -> bool:
        if "inventory_applied" in data:
            value = data.get("inventory_applied")
            if isinstance(value, bool):
                return value
            return str(value or "").strip().lower() in {"1", "true", "yes", "on"}
        doc_type = str(data.get("doc_type") or "sale").strip()
        if int(_sales_decimal(data.get("workflow_version"))) >= _SALES_WORKFLOW_VERSION:
            return _sales_status_requires_inventory(_sales_workflow_status(data), doc_type)
        return doc_type in {"sale", "return"}

    def _sales_inventory_delta_sign(doc_type: str) -> int:
        if doc_type == "return":
            return 1
        if doc_type in {"sale", "order"}:
            return -1
        return 0

    def _sales_doc_type_label(doc_type: str) -> str:
        return {
            "sale": "Продажа",
            "order": "Заказ",
            "return": "Возврат",
        }.get(doc_type or "", "Продажа")

    def _sales_number_prefix(doc_type: str) -> str:
        return {"sale": "a", "order": "b", "return": "c"}.get(doc_type or "", "a")

    def _sales_document_number(prefix: str, index: int) -> str:
        return f"{prefix}{index:02d}"

    def _next_sales_document_number(session: Session, workspace_owner_id: str, doc_type: str) -> str:
        prefix = _sales_number_prefix(doc_type)
        # Выбираем только номера с нужным префиксом, а не все документы workspace.
        existing_numbers = session.execute(
            select(SaleDocument.number).where(
                SaleDocument.workspace_owner_id == workspace_owner_id,
                SaleDocument.number.ilike(f"{prefix}%"),
            )
        ).scalars().all()
        pattern = re.compile(rf"^{re.escape(prefix)}(\d+)$", re.IGNORECASE)
        used_indexes = [
            int(match.group(1))
            for number in existing_numbers
            for match in [pattern.match(str(number or ""))]
            if match
        ]
        index = (max(used_indexes) + 1) if used_indexes else 1
        while True:
            number = _sales_document_number(prefix, index)
            exists = session.execute(
                select(SaleDocument.id)
                .where(
                    SaleDocument.workspace_owner_id == workspace_owner_id,
                    SaleDocument.number == number,
                )
                .limit(1)
            ).scalar_one_or_none()
            if not exists:
                return number
            index += 1

    def _sales_document_data(row: SaleDocument) -> dict[str, Any]:
        data = row.data if isinstance(row.data, dict) else {}
        lines = data.get("lines") if isinstance(data.get("lines"), list) else []
        if not lines:
            ibox_payload = data.get("ibox_payload")
            if isinstance(ibox_payload, dict):
                lines = ibox_sales_document_lines(ibox_payload)
        paid_amount = _sales_decimal(data.get("paid_amount"))
        amount_value = _sales_decimal(row.amount)
        doc_type = str(data.get("doc_type") or "sale")
        status = _sales_workflow_status(data)
        raw_debt_amount = max(Decimal("0"), amount_value - paid_amount)
        debt_amount = raw_debt_amount if _sales_status_records_debt(status, doc_type) else Decimal("0")
        payment_progress = 0
        if amount_value > 0:
            paid_for_progress = max(Decimal("0"), min(paid_amount, amount_value))
            payment_progress = int(
                ((paid_for_progress / amount_value) * Decimal("100")).quantize(
                    Decimal("1"), rounding=ROUND_HALF_UP
                )
            )
        payment_status = (
            "paid"
            if amount_value <= 0 or paid_amount >= amount_value
            else "partial"
            if paid_amount > 0
            else "unpaid"
        )
        date_from = str(data.get("date") or "")
        date_to = str(data.get("date_to") or "")
        date_label = f"{date_from} - {date_to}" if date_from and date_to and date_to != date_from else date_from
        item = {
            "id": row.id,
            "number": row.number,
            "date": date_from,
            "date_to": date_to,
            "date_label": date_label,
            "doc_type": doc_type,
            "doc_type_label": _sales_doc_type_label(doc_type),
            "client": str(data.get("client") or ""),
            "business_segment_id": str(data.get("business_segment_id") or ""),
            "business_segment": str(data.get("business_segment") or ""),
            "business_segment_icon": str(data.get("business_segment_icon") or ""),
            "warehouse": str(data.get("warehouse") or ""),
            "amount": _sales_money_label(row.amount),
            "amount_value": str(amount_value),
            "currency": row.currency,
            "paid_amount": _sales_money_label(paid_amount),
            "paid_value": str(paid_amount),
            "payment_status": payment_status,
            "debt_amount": _sales_money_label(debt_amount if debt_amount > 0 else 0),
            "debt_value": str(debt_amount if debt_amount > 0 else 0),
            "has_debt": debt_amount > 0,
            # Долг в отчётности появляется только на определённых статусах, а
            # оплатить документ можно с самого начала — поэтому кнопка оплаты
            # опирается на остаток к оплате, а не на «бухгалтерский» долг.
            "outstanding_amount": _sales_money_label(raw_debt_amount),
            "outstanding_value": str(raw_debt_amount),
            "payment_progress": payment_progress,
            "payment_type": str(data.get("payment_type") or ""),
            "payment_lines": [
                dict(payment)
                for payment in (data.get("payment_lines") if isinstance(data.get("payment_lines"), list) else [])
                if isinstance(payment, dict)
            ],
            "status": status,
            "status_label": _sales_status_label(status),
            "inventory_applied": _sales_inventory_applied(data),
            "debt_recognized": _sales_status_records_debt(status, doc_type),
            "profit_recognized": _sales_status_records_profit(status, doc_type),
            "manager": str(data.get("manager") or ""),
            "note": str(data.get("note") or ""),
            "price_type_id": str(data.get("price_type_id") or ""),
            "price_type": str(data.get("price_type") or ""),
            "counterparty_id": str(row.counterparty_id or data.get("counterparty_id") or ""),
            "crm_record_id": str(data.get("crm_record_id") or ""),
            "source_sale_id": str(data.get("source_sale_id") or ""),
            "source_order_id": str(data.get("source_order_id") or ""),
            "converted_sale_id": str(data.get("converted_sale_id") or ""),
            "installation_id": str(data.get("installation_id") or ""),
            "installer_user_id": str(data.get("installer_user_id") or ""),
            "installer_name": str(data.get("installer_name") or ""),
            "installation_scheduled_at": str(data.get("installation_scheduled_at") or ""),
            "installation_template_id": str(data.get("installation_template_id") or ""),
            "installation_priority": str(data.get("installation_priority") or "normal"),
            "installation_notes": str(data.get("installation_notes") or ""),
            "installation_attachment_urls": [
                str(url).strip()
                for url in (
                    data.get("installation_attachment_urls")
                    if isinstance(data.get("installation_attachment_urls"), list)
                    else []
                )
                if str(url).strip()
            ],
            "installation_status": str(data.get("installation_status") or ""),
            "installation_conflict_warning": str(data.get("installation_conflict_warning") or ""),
            "lines": lines,
            "updated_at": row.updated_at,
        }
        item["detail_json"] = {
            key: value
            for key, value in item.items()
            if key != "updated_at"
        }
        return item

    def _sales_crm_index(rows: list[CrmRecord], stages: list[dict[str, str]]) -> dict[str, Any]:
        records_by_id: dict[str, CrmRecord] = {}
        deals_by_counterparty: dict[str, CrmRecord] = {}
        deals_by_client: dict[str, CrmRecord] = {}
        tasks_by_deal: dict[str, list[CrmRecord]] = {}
        tasks_by_counterparty: dict[str, list[CrmRecord]] = {}
        tasks_by_client: dict[str, list[CrmRecord]] = {}

        for row in rows:
            data = _json_object(row.data)
            records_by_id[row.id] = row
            counterparty_id = str(row.counterparty_id or data.get("counterparty_id") or "").strip()
            client_key = str(data.get("client") or "").strip().casefold()
            if row.item_type == "deal":
                if counterparty_id:
                    deals_by_counterparty.setdefault(counterparty_id, row)
                if client_key:
                    deals_by_client.setdefault(client_key, row)
                continue
            if row.item_type != "task":
                continue
            related_deal_id = str(data.get("related_deal_id") or "").strip()
            if related_deal_id:
                tasks_by_deal.setdefault(related_deal_id, []).append(row)
            if counterparty_id:
                tasks_by_counterparty.setdefault(counterparty_id, []).append(row)
            if client_key:
                tasks_by_client.setdefault(client_key, []).append(row)

        return {
            "records_by_id": records_by_id,
            "deals_by_counterparty": deals_by_counterparty,
            "deals_by_client": deals_by_client,
            "tasks_by_deal": tasks_by_deal,
            "tasks_by_counterparty": tasks_by_counterparty,
            "tasks_by_client": tasks_by_client,
            "stages": stages,
        }

    def _sales_crm_links(
        item: dict[str, Any], index: dict[str, Any]
    ) -> tuple[CrmRecord | None, CrmRecord | None]:
        records_by_id = index["records_by_id"]
        counterparty_id = str(item.get("counterparty_id") or "").strip()
        client_key = str(item.get("client") or "").strip().casefold()
        direct_record = records_by_id.get(str(item.get("crm_record_id") or "").strip())
        linked_deal = direct_record if direct_record and direct_record.item_type == "deal" else None
        if direct_record and direct_record.item_type == "task":
            direct_data = _json_object(direct_record.data)
            linked_deal = records_by_id.get(str(direct_data.get("related_deal_id") or "").strip())
            if linked_deal and linked_deal.item_type != "deal":
                linked_deal = None
        if linked_deal is None and counterparty_id:
            linked_deal = index["deals_by_counterparty"].get(counterparty_id)
        if linked_deal is None and client_key:
            linked_deal = index["deals_by_client"].get(client_key)
        return linked_deal, direct_record

    # Отдельно от _sales_crm_context: этап нужен ещё до отбора документов,
    # чтобы работал фильтр по этапам CRM, а полный контекст со списком задач
    # считается уже только для текущей страницы журнала.
    def _sales_crm_stage_context(item: dict[str, Any], index: dict[str, Any]) -> dict[str, str]:
        linked_deal, direct_record = _sales_crm_links(item, index)
        status_record = linked_deal or direct_record
        if not status_record:
            return {"crm_status": "", "crm_status_label": "Не назначен"}
        status_data = _json_object(status_record.data)
        if status_record.item_type == "deal":
            stage = _crm_stage_for_value(
                status_data.get("stage_id") or status_data.get("stage"),
                index["stages"],
            )
            return {"crm_status": stage["id"], "crm_status_label": stage["title"]}
        crm_status = str(status_record.status or "new")
        return {"crm_status": crm_status, "crm_status_label": _crm_status_label(crm_status)}

    def _sales_crm_context(item: dict[str, Any], index: dict[str, Any]) -> dict[str, Any]:
        counterparty_id = str(item.get("counterparty_id") or "").strip()
        client_key = str(item.get("client") or "").strip().casefold()
        linked_deal, direct_record = _sales_crm_links(item, index)
        stage_context = _sales_crm_stage_context(item, index)
        crm_status = stage_context["crm_status"]
        crm_status_label = stage_context["crm_status_label"]

        completed_tasks: list[dict[str, Any]] = []
        seen: set[str] = set()
        task_keys: set[str] = set()
        completed_task_keys: set[str] = set()

        def add_task(
            key: str,
            title: Any,
            *,
            completed_at: Any = "",
            due_date: Any = "",
            assignee: Any = "",
            checklist: Any = None,
        ) -> None:
            title_value = re.sub(r"\s+", " ", str(title or "")).strip()
            if not title_value or key in seen:
                return
            seen.add(key)
            checklist_values = [
                re.sub(r"\s+", " ", str(entry or "")).strip()
                for entry in (checklist if isinstance(checklist, list) else [])
                if re.sub(r"\s+", " ", str(entry or "")).strip()
            ][:12]
            completed_tasks.append(
                {
                    "title": title_value[:500],
                    "completed_at": str(completed_at or "")[:16].replace("T", " "),
                    "due_date": str(due_date or "")[:16].replace("T", " "),
                    "assignee": re.sub(r"\s+", " ", str(assignee or "")).strip()[:120],
                    "checklist": checklist_values,
                }
            )

        activity_records = [record for record in (linked_deal, direct_record) if record]
        for record in dict.fromkeys(activity_records):
            data = _json_object(record.data)
            raw_events = data.get("activity_log") if isinstance(data.get("activity_log"), list) else []
            for position, event in enumerate(raw_events):
                if not isinstance(event, dict) or event.get("kind") != "task":
                    continue
                task_key = f"event:{record.id}:{position}"
                task_title = re.sub(
                    r"\s+",
                    " ",
                    str(event.get("detail") or event.get("action") or ""),
                ).strip()
                if not task_title:
                    continue
                task_keys.add(task_key)
                if not event.get("completed"):
                    continue
                completed_task_keys.add(task_key)
                add_task(
                    task_key,
                    task_title,
                    completed_at=event.get("at"),
                    due_date=event.get("due_date"),
                    assignee=event.get("assignee") or event.get("actor"),
                    checklist=event.get("checklist"),
                )

        task_rows: list[CrmRecord] = []
        if direct_record and direct_record.item_type == "task":
            task_rows.append(direct_record)
        if linked_deal:
            task_rows.extend(index["tasks_by_deal"].get(linked_deal.id, []))
        if counterparty_id:
            task_rows.extend(index["tasks_by_counterparty"].get(counterparty_id, []))
        elif client_key:
            task_rows.extend(index["tasks_by_client"].get(client_key, []))
        unique_task_rows = {task.id: task for task in task_rows}
        for task in unique_task_rows.values():
            data = _json_object(task.data)
            task_key = f"record:{task.id}"
            if not re.sub(r"\s+", " ", str(task.title or "")).strip():
                continue
            task_keys.add(task_key)
            if task.status != "done":
                continue
            completed_task_keys.add(task_key)
            add_task(
                task_key,
                task.title,
                completed_at=task.updated_at.isoformat() if task.updated_at else "",
                due_date=task.due_date or data.get("due_date") or data.get("date"),
                assignee=data.get("responsible"),
            )

        completed_tasks.sort(
            key=lambda task: str(task.get("completed_at") or task.get("due_date") or ""),
            reverse=True,
        )
        visible_tasks = completed_tasks[:50]
        return {
            "crm_status": crm_status,
            "crm_status_label": crm_status_label,
            "completed_tasks": visible_tasks,
            "completed_tasks_count": len(completed_tasks),
            "task_total_count": len(task_keys),
            "task_completed_count": len(completed_task_keys),
        }

    def _sales_debt_timing(due_date: str, today: date) -> dict[str, Any]:
        clean_due_date = str(due_date or "").strip()
        try:
            due = datetime.strptime(clean_due_date[:10], "%Y-%m-%d").date() if clean_due_date else None
        except ValueError:
            due = None
        if not due:
            return {
                "due_date": clean_due_date,
                "due_label": clean_due_date or "Без срока",
                "days_overdue": 0,
                "days_until": None,
                "state": "none",
                "state_label": "Без срока",
                "aging": "none",
                "aging_label": "Без срока",
                "priority": 3,
                "sort_date": "9999-12-31",
            }
        days = (due - today).days
        if days < 0:
            overdue = abs(days)
            if overdue <= 7:
                aging = "1-7"
            elif overdue <= 30:
                aging = "8-30"
            else:
                aging = "31+"
            return {
                "due_date": clean_due_date,
                "due_label": clean_due_date,
                "days_overdue": overdue,
                "days_until": days,
                "state": "overdue",
                "state_label": f"Просрочено {overdue} дн.",
                "aging": aging,
                "aging_label": f"{aging} дн.",
                "priority": 0,
                "sort_date": clean_due_date,
            }
        if days == 0:
            return {
                "due_date": clean_due_date,
                "due_label": "Сегодня",
                "days_overdue": 0,
                "days_until": 0,
                "state": "today",
                "state_label": "Срок сегодня",
                "aging": "today",
                "aging_label": "Сегодня",
                "priority": 1,
                "sort_date": clean_due_date,
            }
        return {
            "due_date": clean_due_date,
            "due_label": clean_due_date,
            "days_overdue": 0,
            "days_until": days,
            "state": "upcoming",
            "state_label": f"Через {days} дн.",
            "aging": "future",
            "aging_label": "Предстоящий",
            "priority": 2,
            "sort_date": clean_due_date,
        }

    def _sales_document_age_label(document_date: Any, today: date) -> str:
        clean_document_date = str(document_date or "").strip()
        try:
            parsed_date = (
                datetime.strptime(clean_document_date[:10], "%Y-%m-%d").date()
                if clean_document_date
                else None
            )
        except ValueError:
            parsed_date = None
        if not parsed_date:
            return ""
        days = max(0, (today - parsed_date).days)
        remainder_100 = days % 100
        remainder_10 = days % 10
        if remainder_10 == 1 and remainder_100 != 11:
            unit = "день"
        elif remainder_10 in {2, 3, 4} and remainder_100 not in {12, 13, 14}:
            unit = "дня"
        else:
            unit = "дней"
        return f"{days} {unit}"

    def _sales_debt_workspace(rows: list[SaleDocument], filters: dict[str, str], q_clean: str, today: date) -> dict[str, Any]:
        clients_map: dict[str, dict[str, Any]] = {}
        totals_by_currency: dict[str, Decimal] = {}
        overdue_by_currency: dict[str, Decimal] = {}
        due_today_by_currency: dict[str, Decimal] = {}
        upcoming_by_currency: dict[str, Decimal] = {}
        documents_count = 0
        overdue_documents_count = 0
        due_today_documents_count = 0
        upcoming_documents_count = 0

        for row in rows:
            item = _sales_document_data(row)
            if item["doc_type"] != "sale":
                continue
            debt_value = _sales_decimal(item.get("debt_value"))
            if debt_value <= 0:
                continue
            if filters["client"] and item["client"] != filters["client"]:
                continue
            hay = " ".join(
                [
                    str(item.get("number") or ""),
                    str(item.get("client") or ""),
                    str(item.get("warehouse") or ""),
                    str(item.get("manager") or ""),
                    str(item.get("status_label") or ""),
                    str(item.get("doc_type_label") or ""),
                ]
            ).lower()
            if q_clean and q_clean not in hay:
                continue

            timing = _sales_debt_timing(str(item.get("date_to") or item.get("date") or ""), today)
            currency = str(item.get("currency") or "UZS").upper()
            client_name = str(item.get("client") or "").strip() or "Клиент не указан"
            client_key = client_name.casefold()
            client_bucket = clients_map.setdefault(
                client_key,
                {
                    "client": client_name,
                    "documents": [],
                    "totals": {},
                    "managers": {},
                    "documents_count": 0,
                    "overdue_count": 0,
                    "due_today_count": 0,
                    "upcoming_count": 0,
                    "nearest_due": "",
                    "nearest_due_label": "Без срока",
                    "priority": 3,
                    "max_days_overdue": 0,
                },
            )
            doc = {
                **item,
                **timing,
                "debt_label": _sales_money_label(debt_value),
            }
            client_bucket["documents"].append(doc)
            client_bucket["documents_count"] += 1
            client_bucket["totals"][currency] = client_bucket["totals"].get(currency, Decimal("0")) + debt_value
            if item.get("manager"):
                manager = str(item.get("manager") or "")
                client_bucket["managers"][manager] = client_bucket["managers"].get(manager, 0) + 1
            client_bucket["priority"] = min(client_bucket["priority"], timing["priority"])
            if timing["sort_date"] != "9999-12-31":
                if not client_bucket["nearest_due"] or timing["sort_date"] < client_bucket["nearest_due"]:
                    client_bucket["nearest_due"] = timing["sort_date"]
                    client_bucket["nearest_due_label"] = timing["due_label"]
            client_bucket["max_days_overdue"] = max(client_bucket["max_days_overdue"], int(timing["days_overdue"] or 0))

            totals_by_currency[currency] = totals_by_currency.get(currency, Decimal("0")) + debt_value
            documents_count += 1
            if timing["state"] == "overdue":
                overdue_documents_count += 1
                client_bucket["overdue_count"] += 1
                overdue_by_currency[currency] = overdue_by_currency.get(currency, Decimal("0")) + debt_value
            elif timing["state"] == "today":
                due_today_documents_count += 1
                client_bucket["due_today_count"] += 1
                due_today_by_currency[currency] = due_today_by_currency.get(currency, Decimal("0")) + debt_value
            else:
                upcoming_documents_count += 1
                client_bucket["upcoming_count"] += 1
                upcoming_by_currency[currency] = upcoming_by_currency.get(currency, Decimal("0")) + debt_value

        clients_view: list[dict[str, Any]] = []
        for bucket in clients_map.values():
            bucket["documents"].sort(key=lambda doc: (doc["priority"], doc["sort_date"], str(doc.get("number") or "")))
            managers = sorted(bucket["managers"].items(), key=lambda item: (-item[1], item[0]))
            bucket["manager"] = managers[0][0] if managers else "Без ответственного"
            bucket["totals_list"] = [
                {"currency": currency, "amount": _sales_money_label(amount), "amount_value": str(amount)}
                for currency, amount in sorted(bucket["totals"].items())
                if amount
            ]
            bucket["status"] = "overdue" if bucket["overdue_count"] else "today" if bucket["due_today_count"] else "upcoming"
            bucket["status_label"] = (
                f"Просрочено: {bucket['overdue_count']}"
                if bucket["overdue_count"]
                else f"Срок сегодня: {bucket['due_today_count']}"
                if bucket["due_today_count"]
                else "В графике"
            )
            clients_view.append(bucket)
        clients_view.sort(
            key=lambda bucket: (
                bucket["priority"],
                -int(bucket["max_days_overdue"] or 0),
                bucket["nearest_due"] or "9999-12-31",
                str(bucket["client"]).casefold(),
            )
        )

        def money_list(source: dict[str, Decimal]) -> list[dict[str, str]]:
            return [
                {"currency": currency, "amount": _sales_money_label(amount), "amount_value": str(amount)}
                for currency, amount in sorted(source.items())
                if amount
            ]

        return {
            "clients": clients_view,
            "clients_count": len(clients_view),
            "documents_count": documents_count,
            "overdue_documents_count": overdue_documents_count,
            "due_today_documents_count": due_today_documents_count,
            "upcoming_documents_count": upcoming_documents_count,
            "totals": money_list(totals_by_currency),
            "overdue_totals": money_list(overdue_by_currency),
            "due_today_totals": money_list(due_today_by_currency),
            "upcoming_totals": money_list(upcoming_by_currency),
        }

    def _sales_product_option(
        row: Product,
        active_sales_price_types: list[dict[str, Any]],
        price_types: list[dict[str, Any]],
        usd_rate: Decimal,
    ) -> dict[str, Any]:
        row_data = _json_object(row.data)
        product_view = {
            "id": row.id,
            "name": row.name,
            "kind": str(row_data.get("kind") or "product"),
            "category": str(row_data.get("category") or ""),
            "sku": row.sku,
            "barcode": row.barcode,
            "unit": str(row_data.get("unit") or "Штука"),
            "stocks": _product_stocks(row),
            "prices": row_data.get("prices") if isinstance(row_data.get("prices"), list) else [],
            "price_by_type": {},
        }
        for price_type in active_sales_price_types:
            price, price_currency = _calculated_product_price(product_view, price_type, price_types, usd_rate)
            product_view["price_by_type"][str(price_type.get("id") or "")] = {
                "price": price,
                "currency": price_currency,
            }
        return product_view

    def _sales_document_payload(form: Any) -> tuple[dict[str, Any], Decimal, str]:
        doc_type = str(form.get("doc_type") or "sale").strip()
        if doc_type not in {"sale", "order", "return"}:
            doc_type = "sale"
        currency = str(form.get("currency") or "UZS").strip().upper()[:3] or "UZS"
        products = list(form.getlist("line_product"))
        warehouses = list(form.getlist("line_warehouse"))
        quantities = list(form.getlist("line_quantity"))
        prices = list(form.getlist("line_price"))
        lines: list[dict[str, str]] = []
        total = Decimal("0")
        first_warehouse = str(form.get("warehouse") or "").strip()
        for idx in range(max(len(products), len(warehouses), len(quantities), len(prices), 1)):
            product = str(products[idx] if idx < len(products) else "").strip()
            warehouse = str(warehouses[idx] if idx < len(warehouses) else "").strip() or "Основной склад"
            quantity = _sales_decimal_strict(quantities[idx] if idx < len(quantities) else "", "Количество")
            price = _sales_decimal_strict(prices[idx] if idx < len(prices) else "", "Цена")
            if not product and not quantity and not price:
                continue
            if not product:
                raise ValueError("В строке позиции не выбран товар или услуга")
            if quantity < 0:
                raise ValueError("Количество не может быть отрицательным")
            if price < 0:
                raise ValueError("Цена не может быть отрицательной")
            if quantity <= 0:
                quantity = Decimal("1")
            line_total = quantity * price
            if not first_warehouse:
                first_warehouse = warehouse
            total += line_total
            lines.append(
                {
                    "product": product,
                    "warehouse": warehouse,
                    "quantity": str(quantity.normalize() if quantity else ""),
                    "price": str(price.normalize() if price else ""),
                    "total": str(line_total.normalize() if line_total else "0"),
                }
            )
        if not lines:
            raise ValueError("Добавьте хотя бы один товар или услугу")
        if total <= 0:
            raise ValueError("Сумма продажи должна быть больше 0")
        amount = total
        paid_amount = _sales_decimal_strict(form.get("paid_amount"), "Оплачено")
        if paid_amount < 0:
            raise ValueError("Оплачено не может быть отрицательным")
        status = "return" if doc_type == "return" else "new"
        payment_lines: list[dict[str, str]] = []
        raw_payment_lines = str(form.get("payment_lines") or "").strip()
        if raw_payment_lines:
            try:
                parsed_payment_lines = json.loads(raw_payment_lines)
            except Exception:
                parsed_payment_lines = []
            if isinstance(parsed_payment_lines, list):
                for payment in parsed_payment_lines:
                    if not isinstance(payment, dict):
                        continue
                    payment_amount = _sales_decimal(payment.get("amount"))
                    if payment_amount <= 0:
                        continue
                    payment_currency = str(payment.get("currency") or currency or "UZS").strip().upper() or "UZS"
                    payment_lines.append(
                        {
                            "account_id": str(payment.get("account_id") or "").strip(),
                            "account": str(payment.get("account") or "").strip(),
                            "type": str(payment.get("type") or "").strip(),
                            "currency": payment_currency[:8],
                            "amount": str(payment_amount.normalize() if payment_amount else "0"),
                        }
                    )
        payment_type = str(form.get("payment_type") or "").strip()
        if not payment_type and payment_lines:
            payment_type = ", ".join(
                dict.fromkeys(str(item.get("type") or "").strip() for item in payment_lines if str(item.get("type") or "").strip())
            )
        data = {
            "doc_type": doc_type,
            "date": str(form.get("date") or "").strip(),
            "date_to": str(form.get("date_to") or form.get("date") or "").strip(),
            "client": str(form.get("client") or "").strip(),
            "business_segment_id": str(form.get("business_segment_id") or "").strip(),
            "warehouse": first_warehouse or "Основной склад",
            "status": status,
            "workflow_version": _SALES_WORKFLOW_VERSION,
            "inventory_applied": doc_type == "return",
            "price_type_id": str(form.get("price_type_id") or "").strip(),
            "price_type": str(form.get("price_type_name") or "").strip(),
            "paid_amount": str(paid_amount.normalize() if paid_amount else "0"),
            "payment_type": payment_type,
            "payment_lines": payment_lines,
            "manager": str(form.get("manager") or "").strip(),
            "note": str(form.get("note") or "").strip(),
            "crm_record_id": str(form.get("crm_record_id") or "").strip(),
            "source_sale_id": str(form.get("source_sale_id") or "").strip(),
            "installer_user_id": str(form.get("installer_user_id") or "").strip(),
            "installation_scheduled_at": str(form.get("installation_scheduled_at") or "").strip(),
            "installation_template_id": str(form.get("installation_template_id") or "").strip(),
            "installation_priority": str(form.get("installation_priority") or "normal").strip().lower(),
            "installation_notes": str(form.get("installation_notes") or "").strip(),
            "installation_attachment_urls": [
                item.strip()
                for item in re.split(
                    r"[\r\n,]+",
                    str(form.get("installation_attachment_urls") or ""),
                )
                if item.strip()
            ],
            "lines": lines,
        }
        return data, amount, currency

    def _normalize_sales_payment_lines(
        workspace_owner_id: str,
        payment_lines: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        if not payment_lines:
            return []
        with session_scope() as session:
            accounts = list(
                session.execute(
                    select(FinanceAccount)
                    .where(
                        FinanceAccount.workspace_owner_id == workspace_owner_id,
                        FinanceAccount.is_active == True,  # noqa: E712
                    )
                    .order_by(FinanceAccount.created_at.asc())
                ).scalars()
            )
        if not accounts:
            raise ValueError("Создайте активный финансовый счёт перед добавлением оплаты")

        accounts_by_id = {str(account.id): account for account in accounts}
        accounts_by_name = {
            str(account.name or "").strip().casefold(): account
            for account in accounts
            if str(account.name or "").strip()
        }
        normalized: list[dict[str, Any]] = []
        for payment in payment_lines:
            if not isinstance(payment, dict) or _sales_decimal(payment.get("amount")) <= 0:
                continue
            clean_id = str(payment.get("account_id") or "").strip()
            clean_label = str(payment.get("account") or payment.get("type") or "").strip()
            account = accounts_by_id.get(clean_id) if clean_id else None
            if account is None and clean_label:
                account = accounts_by_name.get(clean_label.casefold())
            if account is None:
                # Неизвестный account_id не должен блокировать документ: у старых
                # продаж в строках оплаты лежат ярлыки вроде «cash», и жёсткая
                # ошибка ломала и доплату, и досинхронизацию кассы по ним.
                # Совпадение по имени уже проверено выше — дальше первый счёт.
                account = accounts[0]

            item = dict(payment)
            item["account_id"] = str(account.id)
            item["account"] = str(account.name or clean_label)
            item["type"] = str(payment.get("type") or account.name or "Оплата").strip() or "Оплата"
            normalized.append(item)
        return normalized

    def _workspace_today_iso(workspace_owner_id: str) -> str:
        """Сегодняшняя дата в часовом поясе воркспейса."""
        tz_id = normalize_workspace_timezone(
            str(load_workspace_settings(workspace_owner_id).get("timezone") or "")
        )
        try:
            return datetime.now(ZoneInfo(tz_id)).date().isoformat()
        except Exception:
            return datetime.now(timezone.utc).date().isoformat()

    def _document_payment_entries_from_form(
        form: Any,
        document_currency: str,
        debt_amount: Decimal,
        workspace_owner_id: str,
        payment_date: str = "",
    ) -> tuple[list[dict[str, str]], Decimal, str]:
        currency = str(document_currency or "UZS").strip().upper() or "UZS"
        # Без даты платежа входящие оплаты нечем датировать: раньше в строке
        # хранились только сумма и счёт, а дата бралась от документа, из-за чего
        # доплата спустя месяц выглядела как оплата в день продажи.
        entry_date = str(payment_date or "").strip() or _workspace_today_iso(workspace_owner_id)
        rate = _workspace_usd_uzs_rate(workspace_owner_id)
        raw_entries: list[dict[str, Any]] = []
        raw_payment_lines = str(form.get("payment_lines") or "").strip()
        if raw_payment_lines:
            try:
                parsed_payment_lines = json.loads(raw_payment_lines)
            except Exception:
                parsed_payment_lines = []
            if isinstance(parsed_payment_lines, list):
                raw_entries = [item for item in parsed_payment_lines if isinstance(item, dict)]
        if not raw_entries:
            raw_entries = [
                {
                    "amount": form.get("payment_amount"),
                    "currency": form.get("payment_currency") or currency,
                    "type": form.get("payment_type") or form.get("payment_account") or "Оплата",
                    "account": form.get("payment_account") or "Наличные",
                    "account_id": form.get("payment_account_id") or "",
                }
            ]
        payment_lines: list[dict[str, str]] = []
        paid_in_document_currency = Decimal("0")
        for item in raw_entries:
            payment_amount = _sales_decimal(item.get("amount"))
            if payment_amount <= 0:
                continue
            payment_currency = str(item.get("currency") or currency).strip().upper() or currency
            converted_amount = _convert_product_currency(payment_amount, payment_currency, currency, rate)
            if converted_amount <= 0:
                continue
            remaining = debt_amount - paid_in_document_currency
            if remaining <= 0:
                break
            if converted_amount > remaining:
                converted_amount = remaining
                payment_amount = _convert_product_currency(converted_amount, currency, payment_currency, rate)
            account_label = str(item.get("account") or item.get("type") or "Наличные").strip() or "Наличные"
            payment_type = str(item.get("type") or account_label or "Оплата").strip() or "Оплата"
            payment_lines.append(
                {
                    "amount": _decimal_plain_text(payment_amount),
                    "currency": payment_currency[:8],
                    "type": payment_type,
                    "account": account_label,
                    "account_id": str(item.get("account_id") or "").strip(),
                    "date": str(item.get("date") or "").strip() or entry_date,
                }
            )
            paid_in_document_currency += converted_amount
        if not payment_lines and debt_amount > 0:
            payment_lines.append(
                {
                    "amount": _decimal_plain_text(debt_amount),
                    "currency": currency,
                    "type": "Оплата",
                    "account": "Наличные",
                    "account_id": "",
                    "date": entry_date,
                }
            )
            paid_in_document_currency = debt_amount
        payment_lines = [
            {
                **item,
                "amount": _decimal_plain_text(_sales_decimal(item.get("amount"))),
            }
            for item in _normalize_sales_payment_lines(workspace_owner_id, payment_lines)
        ]
        payment_type = ", ".join(
            dict.fromkeys(str(item.get("type") or "").strip() for item in payment_lines if str(item.get("type") or "").strip())
        )
        return payment_lines, paid_in_document_currency, payment_type or "Оплата"

    def _delete_sales_cash_transactions(workspace_owner_id: str, sale_id: str) -> None:
        clean_sale_id = str(sale_id or "").strip()
        if not clean_sale_id:
            return
        with session_scope() as session:
            tx_ids = list(
                session.execute(
                    select(Transaction.id).where(
                        Transaction.workspace_owner_id == workspace_owner_id,
                        Transaction.data.op("->>")("source") == "sales",
                        Transaction.data.op("->>")("sales_document_id") == clean_sale_id,
                    )
                ).scalars()
            )
        for tx_id in tx_ids:
            delete_transaction(workspace_owner_id, str(tx_id))

    def _document_created_at_with_time(workspace_owner_id: str, raw_date: Any) -> str:
        """Дата документа плюс фактическое время.

        В кассу уходила голая дата «YYYY-MM-DD», и все операции показывали 00:00.
        Дату оставляем документной — по ней считают периоды и отчёты, — а время
        берём текущее в часовом поясе воркспейса, чтобы колонка «Дата создания»
        показывала реальный момент проведения.
        """
        value = str(raw_date or "").strip()
        if not value or "T" in value:
            return value
        tz_id = normalize_workspace_timezone(
            str(load_workspace_settings(workspace_owner_id).get("timezone") or "")
        )
        try:
            now_local = datetime.now(ZoneInfo(tz_id))
        except Exception:
            now_local = datetime.now(timezone.utc)
        return f"{value}T{now_local:%H:%M:%S}"

    def _sync_sales_cash_transactions(
        workspace_owner_id: str,
        *,
        sale_id: str,
        sale_number: str,
        data: dict[str, Any],
        amount: Decimal,
        currency: str,
        user: dict[str, Any] | None = None,
    ) -> None:
        doc_type = str(data.get("doc_type") or "sale").strip()
        payment_rows: list[dict[str, Any]] = []
        for payment in data.get("payment_lines") if isinstance(data.get("payment_lines"), list) else []:
            if not isinstance(payment, dict):
                continue
            payment_amount = _sales_decimal(payment.get("amount"))
            if payment_amount <= 0:
                continue
            payment_rows.append(
                {
                    "amount": payment_amount,
                    "account_id": str(payment.get("account_id") or "").strip(),
                    "account": str(payment.get("account") or "").strip(),
                    "type": str(payment.get("type") or "").strip(),
                    "currency": str(payment.get("currency") or currency or "UZS").strip().upper() or "UZS",
                }
            )
        paid_amount = _sales_decimal(data.get("paid_amount"))
        if not payment_rows and paid_amount > 0:
            payment_rows.append(
                {
                    "amount": paid_amount,
                    "account_id": "",
                    "account": "",
                    "type": str(data.get("payment_type") or "Оплата").strip(),
                    "currency": currency,
                }
            )
        if payment_rows:
            payment_rows = _normalize_sales_payment_lines(workspace_owner_id, payment_rows)
        _delete_sales_cash_transactions(workspace_owner_id, sale_id)
        if not payment_rows:
            return
        tx_type = "expense" if doc_type == "return" else "income"
        actor_name = str((user or {}).get("name") or (user or {}).get("username") or "").strip()
        employee_id = str((user or {}).get("user_id") or (user or {}).get("id") or "").strip()
        for idx, payment in enumerate(payment_rows, start=1):
            account_id = str(payment.get("account_id") or "").strip()
            tx_data: dict[str, Any] = {
                "amount": payment["amount"],
                "currency": str(payment.get("currency") or currency or "UZS").strip().upper() or "UZS",
                "type": tx_type,
                "status": "confirmed",
                "is_confirmed": True,
                "category": "Возврат продажи" if doc_type == "return" else "Продажа",
                "client": str(data.get("client") or ""),
                "employee_id": employee_id,
                "created_at": _document_created_at_with_time(workspace_owner_id, data.get("date")),
                "note": f"{'Возврат' if doc_type == 'return' else 'Продажа'} {sale_number}",
                "data": {
                    "source": "sales",
                    "sales_document_id": sale_id,
                    "sales_number": sale_number,
                    "sales_doc_type": doc_type,
                    "sales_amount": _decimal_plain_text(amount),
                    "payment_index": idx,
                    "payment_type": str(payment.get("type") or ""),
                    "payment_account_id": account_id,
                    "payment_account": str(payment.get("account") or ""),
                    "manager": actor_name,
                },
            }
            if tx_type == "expense":
                tx_data["from_pocket_id"] = account_id
                tx_data["from_account_id"] = account_id
            else:
                tx_data["to_pocket_id"] = account_id
                tx_data["to_account_id"] = account_id
            create_transaction(workspace_owner_id, tx_data)

    def _sales_cash_payment_count(data: dict[str, Any]) -> int:
        count = 0
        for payment in data.get("payment_lines") if isinstance(data.get("payment_lines"), list) else []:
            if isinstance(payment, dict) and _sales_decimal(payment.get("amount")) > 0:
                count += 1
        if count:
            return count
        return 1 if _sales_decimal(data.get("paid_amount")) > 0 else 0

    # Троттлинг страховочной синхронизации на GET /api/transactions: сканировать
    # продажи не чаще раза в 30 с на workspace — при сохранении/оплате продажи
    # синхронизация и так выполняется напрямую (_sync_sales_cash_transactions).
    _sales_cash_ensure_ts: dict[str, float] = {}
    _SALES_CASH_ENSURE_TTL = 30.0

    def _ensure_sales_cash_transactions(workspace_owner_id: str) -> None:
        now = time.monotonic()
        last = _sales_cash_ensure_ts.get(workspace_owner_id, 0.0)
        if now - last < _SALES_CASH_ENSURE_TTL:
            return
        _sales_cash_ensure_ts[workspace_owner_id] = now
        with session_scope() as session:
            sale_rows = list(
                session.execute(
                    select(SaleDocument)
                    .where(SaleDocument.workspace_owner_id == workspace_owner_id)
                    .order_by(SaleDocument.updated_at.desc())
                    .limit(500)
                ).scalars()
            )
            sales_doc_id = Transaction.data.op("->>")("sales_document_id")
            tx_counts = {
                str(doc_id or ""): int(count or 0)
                for doc_id, count in session.execute(
                    select(sales_doc_id, func.count(Transaction.id))
                    .where(
                        Transaction.workspace_owner_id == workspace_owner_id,
                        Transaction.data.op("->>")("source") == "sales",
                    )
                    .group_by(sales_doc_id)
                ).all()
                if str(doc_id or "").strip()
            }
        for row in sale_rows:
            data = _json_object(row.data)
            expected = _sales_cash_payment_count(data)
            if expected <= 0:
                continue
            if tx_counts.get(str(row.id), 0) == expected:
                continue
            _sync_sales_cash_transactions(
                workspace_owner_id,
                sale_id=str(row.id),
                sale_number=str(row.number or ""),
                data=data,
                amount=_sales_decimal(row.amount),
                currency=str(row.currency or data.get("currency") or "UZS").strip().upper() or "UZS",
                user=None,
            )

    def _installer_request_scope(request: Request) -> tuple[str | None, str, bool]:
        user = request.session.get("user") or {}
        wid = str(user.get("workspace_owner_id") or user.get("user_id") or "").strip()
        if not valid_workspace_owner_id(wid):
            return None, "", False
        role_key = _employee_role_key(user)
        installer_user_id = _session_user_id(user) if role_key == "installer" else ""
        return wid, installer_user_id, not bool(installer_user_id)

    def _installer_local_datetime(value: datetime | None, timezone_name: str) -> str:
        if value is None:
            return ""
        current = value
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        try:
            current = current.astimezone(ZoneInfo(timezone_name))
        except Exception:
            current = current.astimezone(timezone.utc)
        return current.strftime("%Y-%m-%dT%H:%M")

    def _installer_order_line_payload(
        raw_line: dict[str, Any],
        *,
        index: int,
        currency: str,
    ) -> dict[str, Any]:
        line = dict(raw_line)
        product = line.get("product")
        product_data = product if isinstance(product, dict) else {}
        product_name = next(
            (
                str(value).strip()
                for value in (
                    line.get("product_name"),
                    product if not isinstance(product, dict) else "",
                    product_data.get("name"),
                    product_data.get("title"),
                    line.get("name"),
                    line.get("title"),
                    line.get("service_name"),
                    line.get("item_name"),
                )
                if str(value or "").strip()
            ),
            f"Позиция {index + 1}",
        )
        line["product_name"] = product_name
        line["quantity"] = line.get("quantity", line.get("qty", line.get("count", "1")))
        line["total"] = line.get(
            "total",
            line.get("amount", line.get("sum", line.get("price", 0))),
        )
        line["currency"] = str(line.get("currency") or currency or "UZS")
        return line

    def _installer_order_payload(
        session: Any,
        order: InstallationOrder,
        *,
        timezone_name: str,
        can_manage: bool,
    ) -> dict[str, Any]:
        data = order.data if isinstance(order.data, dict) else {}
        contact = client_contact(session, order.counterparty_id)
        tasks = order_tasks(session, order.id)
        progress = task_progress(tasks)
        client_name = str(data.get("client_name") or contact.get("name") or "Клиент").strip()
        client_phone = str(data.get("client_phone") or contact.get("phone") or "").strip()
        address = str(order.address or data.get("client_address") or contact.get("address") or "").strip()
        lines = data.get("sale_lines")
        if not isinstance(lines, list):
            lines = []
        currency = str(order.currency or "UZS")
        return {
            "id": order.id,
            "number": str(order.number or ""),
            "sale_document_id": str(order.sale_document_id or ""),
            "status": str(order.status or "new"),
            "status_label": status_label(str(order.status or "new")),
            "priority": str(order.priority or "normal"),
            "priority_label": INSTALLATION_PRIORITY_LABELS.get(
                str(order.priority or "normal"),
                str(order.priority or "normal"),
            ),
            "scheduled_at": _installer_local_datetime(order.scheduled_at, timezone_name),
            "scheduled_confirmed": bool(order.scheduled_confirmed),
            "client": {
                "name": client_name,
                "phone": client_phone,
                "address": address,
            },
            "latitude": str(order.latitude or ""),
            "longitude": str(order.longitude or ""),
            "amount": str(order.amount or 0),
            "paid_amount": str(order.paid_amount or 0),
            "currency": currency,
            "installer_name": str(data.get("installer_name") or "").strip(),
            "notes": str(data.get("notes") or "").strip(),
            "result_comment": str(data.get("result_comment") or "").strip(),
            "conflict_warning": str(data.get("conflict_warning") or "").strip(),
            "lines": [
                _installer_order_line_payload(
                    line,
                    index=index,
                    currency=currency,
                )
                for index, line in enumerate(lines)
                if isinstance(line, dict)
            ],
            "tasks": [
                {
                    "id": task.id,
                    "title": str(task.title or ""),
                    "description": str(task.description or ""),
                    "required": bool(task.is_required),
                    "done": bool(task.is_done),
                    "comment": str(task.comment or ""),
                }
                for task in tasks
            ],
            "progress": progress,
            "completion_blockers": completion_blockers(order, tasks),
            "allowed_transitions": sorted(ALLOWED_TRANSITIONS.get(str(order.status or ""), ())),
            "can_manage": can_manage,
        }

    def _installer_api_error(message: str, status_code: int = 400) -> JSONResponse:
        return JSONResponse({"ok": False, "error": message}, status_code=status_code)

    def _installer_csrf_valid(request: Request) -> bool:
        token = (
            request.headers.get("X-CSRF-Token")
            or request.headers.get("x-csrf-token")
            or ""
        )
        return csrf_matches_session(request, token)

    @app.get("/installer", response_class=HTMLResponse, name="installer_app")
    def installer_app(request: Request):
        wid, _installer_user_id, can_manage = _installer_request_scope(request)
        if not wid:
            return RedirectResponse(url="/auth?next=/installer", status_code=302)
        return tpl(
            request,
            "installer.html",
            installer_can_manage=can_manage,
        )

    @app.get("/installer-sw.js", name="installer_service_worker")
    def installer_service_worker():
        path = BASE_DIR / "static" / "installer-sw.js"
        if not path.exists():
            return Response("", media_type="application/javascript", status_code=404)
        return Response(
            path.read_text(encoding="utf-8"),
            media_type="application/javascript",
            headers={
                "Cache-Control": "no-cache",
                "Service-Worker-Allowed": "/",
            },
        )

    @app.get("/api/installer/orders", name="installer_orders_api")
    def installer_orders_api(request: Request):
        wid, installer_user_id, can_manage = _installer_request_scope(request)
        requested_installer_id = str(
            request.query_params.get("installer_user_id") or ""
        ).strip()
        selected_installer_id = installer_user_id
        if can_manage and requested_installer_id:
            selected_installer_id = requested_installer_id
        if not wid:
            return _installer_api_error("Нужно войти заново", 401)
        timezone_name = normalize_workspace_timezone(
            str(load_workspace_settings(wid).get("timezone") or "")
        )
        with session_scope() as session:
            if selected_installer_id:
                rows = installer_orders(
                    session,
                    workspace_owner_id=wid,
                    installer_user_id=selected_installer_id,
                )
            else:
                rows = list(
                    session.execute(
                        select(InstallationOrder)
                        .where(InstallationOrder.workspace_owner_id == wid)
                        .order_by(
                            InstallationOrder.scheduled_at.asc().nulls_last(),
                            InstallationOrder.created_at.desc(),
                        )
                    ).scalars()
                )
            payload = [
                _installer_order_payload(
                    session,
                    row,
                    timezone_name=timezone_name,
                    can_manage=can_manage,
                )
                for row in rows
            ]
        return JSONResponse({"ok": True, "orders": payload})

    @app.post("/api/installer/orders/{order_id}/status", name="installer_order_status_api")
    async def installer_order_status_api(
        request: Request,
        order_id: str,
        background_tasks: BackgroundTasks,
    ):
        if not _installer_csrf_valid(request):
            return _installer_api_error("Форма устарела. Обновите страницу.", 403)
        wid, installer_user_id, can_manage = _installer_request_scope(request)
        if not wid:
            return _installer_api_error("Нужно войти заново", 401)
        try:
            body = await request.json()
        except Exception:
            return _installer_api_error("Некорректные данные")
        target = str((body or {}).get("status") or "").strip()
        result_comment = str((body or {}).get("result_comment") or "").strip()
        user = request.session.get("user") or {}
        actor_id = _session_user_id(user)
        actor_name = str(user.get("name") or user.get("username") or "").strip()
        timezone_name = normalize_workspace_timezone(
            str(load_workspace_settings(wid).get("timezone") or "")
        )
        with session_scope() as session:
            order = load_order(
                session,
                workspace_owner_id=wid,
                order_id=order_id,
                installer_user_id=installer_user_id if not can_manage else "",
            )
            if order is None:
                return _installer_api_error("Заказ установки не найден", 404)
            if result_comment:
                data = order.data if isinstance(order.data, dict) else {}
                order.data = {**data, "result_comment": result_comment}
                flag_modified(order, "data")
            if target == "completed":
                blockers = completion_blockers(order, order_tasks(session, order.id))
                if blockers:
                    return _installer_api_error(blockers[0], 409)
            try:
                set_status(
                    session,
                    order=order,
                    target=target,
                    actor_user_id=actor_id,
                    actor_name=actor_name,
                )
            except InstallationError as exc:
                return _installer_api_error(str(exc), 409)
            payload = _installer_order_payload(
                session,
                order,
                timezone_name=timezone_name,
                can_manage=can_manage,
            )
            order_number = str(order.number or "")
            order_installer_id = str(order.installer_user_id or "")
        # Уведомление шлём после коммита: до него смена статуса может откатиться.
        if target == "completed" and order_installer_id:
            background_tasks.add_task(
                push_notify_users,
                wid,
                [order_installer_id],
                title="Установка завершена",
                body=f"Заказ {order_number} закрыт. Вознаграждение начислено.",
                url="/earnings",
                tag=f"order-{order_id}",
            )
        return JSONResponse({"ok": True, "order": payload})

    @app.post("/api/installer/orders/{order_id}/schedule", name="installer_order_schedule_api")
    async def installer_order_schedule_api(request: Request, order_id: str):
        if not _installer_csrf_valid(request):
            return _installer_api_error("Форма устарела. Обновите страницу.", 403)
        wid, installer_user_id, can_manage = _installer_request_scope(request)
        if not wid:
            return _installer_api_error("Нужно войти заново", 401)
        try:
            body = await request.json()
        except Exception:
            return _installer_api_error("Некорректные данные")
        scheduled_text = str((body or {}).get("scheduled_at") or "").strip()
        confirmed = bool((body or {}).get("confirmed", True))
        if not scheduled_text:
            return _installer_api_error("Выберите дату и время установки")
        timezone_name = normalize_workspace_timezone(
            str(load_workspace_settings(wid).get("timezone") or "")
        )
        try:
            scheduled_at = datetime.fromisoformat(scheduled_text)
            if scheduled_at.tzinfo is None:
                scheduled_at = scheduled_at.replace(tzinfo=ZoneInfo(timezone_name))
            scheduled_at = scheduled_at.astimezone(timezone.utc)
        except (TypeError, ValueError, OSError):
            return _installer_api_error("Укажите корректную дату и время")
        user = request.session.get("user") or {}
        actor_id = _session_user_id(user)
        actor_name = str(user.get("name") or user.get("username") or "").strip()
        with session_scope() as session:
            order = load_order(
                session,
                workspace_owner_id=wid,
                order_id=order_id,
                installer_user_id=installer_user_id if not can_manage else "",
            )
            if order is None:
                return _installer_api_error("Заказ установки не найден", 404)
            reschedule(
                session,
                order=order,
                scheduled_at=scheduled_at,
                actor_user_id=actor_id,
                actor_name=actor_name,
                confirmed=confirmed,
            )
            if confirmed and str(order.status or "") in {
                "accepted",
                "date_negotiation",
                "postponed",
            }:
                try:
                    set_status(
                        session,
                        order=order,
                        target="scheduled",
                        actor_user_id=actor_id,
                        actor_name=actor_name,
                    )
                except InstallationError:
                    pass
            payload = _installer_order_payload(
                session,
                order,
                timezone_name=timezone_name,
                can_manage=can_manage,
            )
        return JSONResponse({"ok": True, "order": payload})

    @app.get("/api/installer/clients", name="installer_clients_api")
    def installer_clients_api(request: Request):
        wid, _installer_user_id, _can_manage = _installer_request_scope(request)
        if not wid:
            return _installer_api_error("Нужно войти заново", 401)
        query = str(request.query_params.get("q") or "").strip().lower()
        with session_scope() as session:
            rows = list(
                session.execute(
                    select(Counterparty)
                    .where(
                        Counterparty.workspace_owner_id == wid,
                        Counterparty.kind.in_(["client", "both"]),
                    )
                    .order_by(Counterparty.name.asc())
                    .limit(500)
                ).scalars()
            )
            clients = []
            for row in rows:
                extra = _counterparty_extra(row)
                name = str(row.name or "")
                phone = str(row.phone or "")
                if query and query not in f"{name} {phone}".lower():
                    continue
                clients.append(
                    {
                        "id": row.id,
                        "name": name,
                        "phone": phone,
                        "address": str(extra.get("address") or ""),
                    }
                )
        return JSONResponse({"ok": True, "clients": clients[:200]})

    @app.post("/api/installer/clients", name="installer_client_create_api")
    async def installer_client_create_api(request: Request):
        if not _installer_csrf_valid(request):
            return _installer_api_error("Форма устарела. Обновите страницу.", 403)
        wid, _installer_user_id, _can_manage = _installer_request_scope(request)
        if not wid:
            return _installer_api_error("Нужно войти заново", 401)
        try:
            body = await request.json()
        except Exception:
            body = {}
        name = " ".join(str((body or {}).get("name") or "").split())
        if not name:
            return _installer_api_error("Укажите название клиента", 400)
        phone = str((body or {}).get("phone") or "").strip()
        address = str((body or {}).get("address") or "").strip()
