    @app.get("/clients", response_class=HTMLResponse, name="clients_get")
    def clients_get(
        request: Request,
        q: str = "",
        territory: str = "",
        category: str = "",
        program: str = "",
        route: str = "",
        status: str = "all",
        client_sort: str = "",
        client_sort_dir: str = "desc",
        page_size: str = "100",
        page: str = "1",
        balance_page: str = "1",
        client: str = "",
    ):
        module_redirect = _employee_module_redirect(request, "clients")
        if module_redirect is not None:
            return module_redirect
        wid, redir = _product_workspace_owner(request)
        if redir:
            return redir
        assert wid is not None
        business_segments = _workspace_business_segments(wid)
        filters = {
            "q": q.strip(),
            "territory": territory.strip(),
            "category": category.strip(),
            "program": program.strip(),
            "route": route.strip(),
            "status": status.strip() or "all",
        }
        q_clean = filters["q"].casefold().replace("ё", "е")
        q_tokens = [
            token
            for token in re.split(r"\s+", q_clean)
            if token and re.sub(r"[^\w]+", "", token)
        ]
        clients_records: list[dict[str, Any]] = []
        client_routes: list[dict[str, Any]] = []
        client_balances: list[dict[str, Any]] = []
        selected_client_card: dict[str, Any] | None = None
        with session_scope() as session:
            (
                balance_by_id,
                balance_by_name,
                last_date_by_id,
                last_date_by_name,
                balance_currency_by_id,
                balance_currency_by_name,
            ) = _sales_rollup_all(session, wid)
            settings_payload = load_workspace_settings(wid)
            raw_calls = settings_payload.get("telephony_calls") if isinstance(settings_payload.get("telephony_calls"), list) else []
            crm_rows_for_contact = list(
                session.execute(
                    select(CrmRecord)
                    .where(CrmRecord.workspace_owner_id == wid)
                    .order_by(CrmRecord.updated_at.desc())
                ).scalars()
            )
            crm_stages_for_clients = _crm_workspace_stages(wid)
            crm_status_by_id, crm_status_by_name = _crm_status_maps_from_records(crm_rows_for_contact, crm_stages_for_clients)
            telegram_subscribers_for_contact = list(
                session.execute(
                    select(TelegramSubscriber)
                    .where(TelegramSubscriber.workspace_owner_id == wid)
                    .order_by(TelegramSubscriber.requested_at.desc())
                ).scalars()
            )

            def digits(value: Any) -> str:
                return "".join(ch for ch in str(value or "") if ch.isdigit())

            def bump_date(current: str, candidate: Any) -> str:
                raw = str(candidate or "").strip()
                if not raw:
                    return current
                return raw if raw > current else current

            def client_last_contact(row: Counterparty, item: dict[str, Any]) -> str:
                names = {
                    str(item.get("name") or "").strip().lower(),
                    str(item.get("official_name") or "").strip().lower(),
                }
                names.discard("")
                best = str(item.get("last_date") or "")
                phone_digits = digits(item.get("phone"))
                telegram_key = str(item.get("telegram") or "").lstrip("@").lower()
                for call in raw_calls:
                    if not isinstance(call, dict):
                        continue
                    call_client = str(call.get("client") or "").strip().lower()
                    call_phone = digits(call.get("phone"))
                    if call_client in names or (phone_digits and call_phone and call_phone.endswith(phone_digits[-9:])):
                        best = bump_date(best, call.get("started_at") or call.get("created_at"))
                for crm_row in crm_rows_for_contact:
                    data = _json_object(crm_row.data)
                    crm_client = str(data.get("client") or "").strip().lower()
                    if crm_row.counterparty_id == row.id or crm_client in names:
                        best = bump_date(best, data.get("date") or data.get("due_date") or crm_row.updated_at.isoformat())
                for subscriber in telegram_subscribers_for_contact:
                    username = str(subscriber.username or "").lstrip("@").lower()
                    sub_phone = digits(subscriber.phone)
                    display_name = str(subscriber.display_name or "").strip().lower()
                    if (
                        (telegram_key and username == telegram_key)
                        or (phone_digits and sub_phone and sub_phone.endswith(phone_digits[-9:]))
                        or (display_name and display_name in names)
                    ):
                        best = bump_date(best, subscriber.requested_at.isoformat() if subscriber.requested_at else "")
                return best

            selected_client_id = client.strip()
            if selected_client_id:
                try:
                    selected_client_card = _client_card_context(
                        session,
                        wid,
                        selected_client_id,
                        balance_by_id=balance_by_id,
                        balance_by_name=balance_by_name,
                        last_date_by_id=last_date_by_id,
                        last_date_by_name=last_date_by_name,
                        balance_currency_by_id=balance_currency_by_id,
                        balance_currency_by_name=balance_currency_by_name,
                        crm_status_by_id=crm_status_by_id,
                        crm_status_by_name=crm_status_by_name,
                    )
                except Exception:
                    logger.exception("Failed to build client card %s", selected_client_id)
                    selected_client_card = None
            rows = list(
                session.execute(
                    select(Counterparty)
                    .where(
                        Counterparty.workspace_owner_id == wid,
                        Counterparty.kind.in_(["client", "both"]),
                    )
                    .order_by(Counterparty.updated_at.desc())
                ).scalars()
            )
            route_map: dict[str, dict[str, Any]] = {}
            for row in rows:
                item = _counterparty_view_data(
                    row,
                    balance_by_id=balance_by_id,
                    balance_by_name=balance_by_name,
                    last_date_by_id=last_date_by_id,
                    last_date_by_name=last_date_by_name,
                    balance_currency_by_id=balance_currency_by_id,
                    balance_currency_by_name=balance_currency_by_name,
                    crm_status_by_id=crm_status_by_id,
                    crm_status_by_name=crm_status_by_name,
                )
                search_fields = " ".join(
                    [
                        item["id"],
                        item["name"],
                        item["official_name"],
                        item["legal_name"],
                        item["phone"],
                        item["telegram_phone"],
                        item["inn"],
                        item["pinfl"],
                        item["code"],
                    ]
                ).casefold().replace("ё", "е")
                compact_search_fields = re.sub(r"[^\w]+", "", search_fields)
                if q_tokens and not all(
                    token in search_fields or re.sub(r"[^\w]+", "", token) in compact_search_fields
                    for token in q_tokens
                ):
                    continue
                if filters["territory"] and item["territory"] != filters["territory"]:
                    continue
                if filters["category"] and item["category"] != filters["category"]:
                    continue
                if filters["program"] and filters["program"] not in item["programs"]:
                    continue
                if filters["route"] and item["route"] != filters["route"]:
                    continue
                if filters["status"] != "all" and item["status"] != filters["status"]:
                    continue
                clients_records.append(item)
                item["last_contact"] = client_last_contact(row, item)
                route_key = item["route"] or "Без маршрута"
                extra = _counterparty_extra(row)
                summary = route_map.setdefault(
                    route_key,
                    {
                        "route": route_key,
                        "territory": item["territory"] or "-",
                        "count": 0,
                        "balance_value": Decimal("0"),
                        "clients": [],
                        "days": set(),
                        "agents": set(),
                    },
                )
                summary["count"] += 1
                summary["balance_value"] += item["balance_value"]
                summary["clients"].append(item["name"])
                if extra.get("route_day"):
                    summary["days"].add(str(extra.get("route_day")))
                if extra.get("route_agent"):
                    summary["agents"].add(str(extra.get("route_agent")))
                if item["balance_value"] > 0:
                    client_balances.append(item)
            client_routes = [
                {
                    "route": key,
                    "territory": value["territory"],
                    "count": value["count"],
                    "balance": _sales_money_label(value["balance_value"]),
                    "clients": ", ".join(value["clients"][:8]),
                    "day": ", ".join(sorted(value["days"])) or "-",
                    "agent": ", ".join(sorted(value["agents"])) or "-",
                }
                for key, value in sorted(route_map.items())
            ]
            client_balances.sort(key=lambda item: item["balance_value"], reverse=True)
            # Кассовые дубли контрагентов несут один и тот же баланс по имени —
            # в должниках оставляем одну строку на имя, телефон берём заполненный.
            deduped_balances: dict[str, dict[str, Any]] = {}
            for item in client_balances:
                key = str(item.get("name") or "").strip().lower()
                kept = deduped_balances.get(key)
                if kept is None:
                    deduped_balances[key] = item
                elif not kept.get("phone") and item.get("phone"):
                    kept["phone"] = item["phone"]
            client_balances = list(deduped_balances.values())
        client_balances_debt_total = sum(
            (item["balance_value"] for item in client_balances),
            Decimal("0"),
        )
        all_clients_records = clients_records
        for directory_number, item in enumerate(all_clients_records, start=1):
            item["directory_number"] = directory_number

        client_sort_keys = {
            "id": ("directory_number", "number"),
            "name": ("name", "text"),
            "official_name": ("official_name", "text"),
            "balance": ("balance_value", "number"),
            "last_date": ("last_date", "date"),
            "segment": ("business_segment", "text"),
            "created_at": ("created_at", "date"),
            "phone": ("phone", "text"),
            "category": ("category", "text"),
        }
        clients_sort_key = client_sort if client_sort in client_sort_keys else ""
        clients_sort_direction = "asc" if client_sort_dir == "asc" else "desc"
        if clients_sort_key:
            value_key, value_kind = client_sort_keys[clients_sort_key]

            def clients_sort_value(item: dict[str, Any]) -> Any:
                value = item.get(value_key)
                if value_kind == "number":
                    return _sales_decimal(value)
                return str(value or "").strip().casefold()

            populated_clients = [item for item in all_clients_records if str(item.get(value_key) or "").strip()]
            empty_clients = [item for item in all_clients_records if not str(item.get(value_key) or "").strip()]
            populated_clients.sort(
                key=clients_sort_value,
                reverse=clients_sort_direction == "desc",
            )
            all_clients_records = populated_clients + empty_clients
        clients_total = len(all_clients_records)
        clients_debt_total = sum(
            (item["balance_value"] for item in all_clients_records if item["balance_value"] > 0),
            Decimal("0"),
        )
        clients_advance_total = sum(
            (abs(item["balance_value"]) for item in all_clients_records if item["balance_value"] < 0),
            Decimal("0"),
        )
        clients_net_total = clients_debt_total - clients_advance_total
        # Итоги по каждой валюте отдельно — доллары не смешиваются с сумами.
        clients_debt_by_ccy: dict[str, Decimal] = {}
        clients_advance_by_ccy: dict[str, Decimal] = {}
        for item in all_clients_records:
            for line in item.get("balance_lines") or []:
                amount = _sales_decimal(line.get("value"))
                if not amount:
                    continue
                ccy = str(line.get("currency") or "UZS").upper()
                if amount > 0:
                    clients_debt_by_ccy[ccy] = clients_debt_by_ccy.get(ccy, Decimal("0")) + amount
                else:
                    clients_advance_by_ccy[ccy] = clients_advance_by_ccy.get(ccy, Decimal("0")) + abs(amount)
        clients_net_lines = []
        for ccy in sorted(set(clients_debt_by_ccy) | set(clients_advance_by_ccy)):
            net = clients_debt_by_ccy.get(ccy, Decimal("0")) - clients_advance_by_ccy.get(ccy, Decimal("0"))
            if not net:
                continue
            clients_net_lines.append(
                {
                    "currency": ccy,
                    "display": _client_balance_display(net),
                    "kind": "debt" if net > 0 else "advance",
                }
            )
        clients_balance_summary = {
            "debt": _sales_money_label(clients_debt_total),
            "debt_display": _client_balance_display(clients_debt_total),
            "advance": _sales_money_label(clients_advance_total),
            "advance_display": _client_balance_display(-clients_advance_total),
            "net": _sales_money_label(clients_net_total),
            "net_display": _client_balance_display(clients_net_total),
            "debt_lines": [
                {"currency": ccy, "display": _client_balance_display(value)}
                for ccy, value in sorted(clients_debt_by_ccy.items())
                if value
            ],
            "advance_lines": [
                {"currency": ccy, "display": _client_balance_display(-value)}
                for ccy, value in sorted(clients_advance_by_ccy.items())
                if value
            ],
            "net_lines": clients_net_lines,
            "debt_count": sum(1 for item in all_clients_records if item["balance_value"] > 0),
            "advance_count": sum(1 for item in all_clients_records if item["balance_value"] < 0),
        }
        client_options = {
            "territories": sorted({item["territory"] for item in all_clients_records if item["territory"]}),
            "categories": sorted({item["category"] for item in all_clients_records if item["category"]}),
            "programs": sorted({program for item in all_clients_records for program in item["programs"] if program}),
            "routes": sorted({item["route"] for item in all_clients_records if item["route"]}),
            "clients": sorted({item["name"] for item in all_clients_records if item["name"]}),
        }

        clients_page_size = _table_page_size(page_size)

        clients_total_pages = max(1, math.ceil(clients_total / clients_page_size))
        clients_page = min(_positive_int(page, 1), clients_total_pages)
        clients_page_start = (clients_page - 1) * clients_page_size
        clients_page_end = clients_page_start + clients_page_size
        clients_records = all_clients_records[clients_page_start:clients_page_end]
        # Карта не пагинируется: в правой таблице нужны также клиенты без
        # локации, чтобы координаты можно было быстро добавить из этого экрана.
        clients_map_records = all_clients_records

        client_balances_total = len(client_balances)
        client_balances_total_pages = max(1, math.ceil(client_balances_total / clients_page_size))
        client_balances_page = min(_positive_int(balance_page, 1), client_balances_total_pages)
        client_balances_start = (client_balances_page - 1) * clients_page_size
        client_balances_end = client_balances_start + clients_page_size
        client_balances = client_balances[client_balances_start:client_balances_end]

        def clients_page_url(target_page: int, *, anchor: str = "clients", page_key: str = "page") -> str:
            pairs = [
                (str(key), str(value))
                for key, value in request.query_params.multi_items()
                if str(key) != page_key
            ]
            pairs.append((page_key, str(target_page)))
            return f"{request.url.path}?{urlencode(pairs, doseq=True)}#{anchor}"

        clients_pagination_pages = _table_pagination_pages(
            clients_page,
            clients_total_pages,
        )
        client_balances_pagination_pages = _table_pagination_pages(
            client_balances_page,
            client_balances_total_pages,
        )
        return tpl(
            request,
            "home_business_module.html",
            variant="user",
            active="clients",
            module=_business_module_context("clients"),
            client_filters=filters,
            client_options=client_options,
            client_business_segments=business_segments,
            clients_records=clients_records,
            clients_sort_key=clients_sort_key,
            clients_sort_direction=clients_sort_direction,
            clients_map_records=clients_map_records,
            clients_total=clients_total,
            clients_page=clients_page,
            clients_page_size=clients_page_size,
            clients_total_pages=clients_total_pages,
            clients_page_from=clients_page_start + 1 if clients_total else 0,
            clients_page_to=min(clients_page_end, clients_total),
            clients_pagination_pages=clients_pagination_pages,
            clients_page_urls={page_no: clients_page_url(page_no) for page_no in clients_pagination_pages},
            clients_prev_page_url=clients_page_url(max(1, clients_page - 1)),
            clients_next_page_url=clients_page_url(min(clients_total_pages, clients_page + 1)),
            clients_balance_summary=clients_balance_summary,
            client_routes=client_routes,
            client_balances=client_balances,
            client_balances_debt_total=_client_balance_display(client_balances_debt_total),
            client_balances_total=client_balances_total,
            client_balances_page=client_balances_page,
            client_balances_total_pages=client_balances_total_pages,
            client_balances_page_from=client_balances_start + 1 if client_balances_total else 0,
            client_balances_page_to=min(client_balances_end, client_balances_total),
            client_balances_pagination_pages=client_balances_pagination_pages,
            client_balances_page_urls={
                page_no: clients_page_url(page_no, anchor="balances", page_key="balance_page")
                for page_no in client_balances_pagination_pages
            },
            client_balances_prev_page_url=clients_page_url(
                max(1, client_balances_page - 1), anchor="balances", page_key="balance_page"
            ),
            client_balances_next_page_url=clients_page_url(
                min(client_balances_total_pages, client_balances_page + 1),
                anchor="balances",
                page_key="balance_page",
            ),
            selected_client_card=selected_client_card,
            flash_ok=request.query_params.get("msg"),
            flash_err=_module_flash_error(request),
        )

    async def _save_client_photo_upload(workspace_owner_id: str, upload: Any) -> str:
        filename = str(getattr(upload, "filename", "") or "").strip()
        if not filename:
            return ""
        suffix = Path(filename).suffix.lower()
        if suffix not in {".jpg", ".jpeg", ".png", ".webp", ".gif"}:
            return ""
        content_type = str(getattr(upload, "content_type", "") or "").lower()
        if content_type and not content_type.startswith("image/"):
            return ""
        payload = await upload.read()
        if not payload:
            return ""
        target_dir = BASE_DIR / "static" / "uploads" / "clients" / re.sub(r"[^a-zA-Z0-9_-]", "_", workspace_owner_id)
        target_dir.mkdir(parents=True, exist_ok=True)
        file_name = f"{uuid.uuid4().hex}{suffix}"
        target = target_dir / file_name
        target.write_bytes(payload)
        return f"/static/uploads/clients/{target_dir.name}/{file_name}"

    def _clean_client_coordinate(value: Any, *, minimum: float, maximum: float) -> str:
        raw = str(value or "").strip().replace(",", ".")
        if not raw:
            return ""
        try:
            number = float(raw)
        except ValueError:
            return ""
        if not (minimum <= number <= maximum):
            return ""
        return f"{number:.6f}".rstrip("0").rstrip(".")

    def _geocode_client_address(address: str) -> tuple[str, str]:
        query = str(address or "").strip()
        if not query:
            return "", ""
        url = "https://nominatim.openstreetmap.org/search?" + urlencode(
            {
                "format": "jsonv2",
                "limit": "1",
                "countrycodes": "uz,kz,kg,tj,tm",
                "q": query,
            }
        )
        request = UrlRequest(
            url,
            headers={
                "Accept": "application/json",
                "User-Agent": "UPOS/2.0 client-location-geocoder",
            },
        )
        try:
            with urlopen(request, timeout=5) as response:
                payload = json.loads(response.read().decode("utf-8") or "[]")
        except Exception:
            return "", ""
        if not isinstance(payload, list) or not payload:
            return "", ""
        first = payload[0] if isinstance(payload[0], dict) else {}
        lat = _clean_client_coordinate(first.get("lat"), minimum=-90, maximum=90)
        lon = _clean_client_coordinate(first.get("lon"), minimum=-180, maximum=180)
        return lat, lon

    @app.post("/clients/save", name="clients_save")
    async def clients_save(request: Request):
        form = await request.form()
        wants_json = "application/json" in str(request.headers.get("accept") or "").lower() or str(form.get("response") or "").strip() == "json"
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            if wants_json:
                return JSONResponse({"ok": False, "error": "Форма устарела. Обновите страницу и повторите."}, status_code=403)
            return RedirectResponse(url="/clients?err=csrf", status_code=302)
        wid, redir = _product_workspace_owner(request)
        if redir:
            if wants_json:
                return JSONResponse({"ok": False, "error": "Нужно войти заново"}, status_code=401)
            return redir
        assert wid is not None
        name = " ".join(str(form.get("name") or "").split())
        if not name:
            if wants_json:
                return JSONResponse({"ok": False, "error": "Название клиента обязательно"}, status_code=400)
            return RedirectResponse(url="/clients?error=" + quote("Название клиента обязательно") + "#clients", status_code=302)
        is_supplier = str(form.get("is_supplier") or "").strip() == "1"
        client_id = str(form.get("client_id") or "").strip()
        phone = str(form.get("phone") or "").strip()
        tax_id = str(form.get("tax_id") or form.get("inn") or "").strip()
        pinfl = str(form.get("pinfl") or "").strip()
        email = str(form.get("email") or "").strip()
        business_segments = _workspace_business_segments(wid)
        selected_segments: list[dict[str, str]] = []
        selected_segment_ids: set[str] = set()
        raw_segment_values = list(form.getlist("business_segment_ids"))
        if not raw_segment_values:
            raw_segment_values = [form.get("business_segment_id")]
        for raw_segment_value in raw_segment_values:
            segment = _business_segment_for_value(raw_segment_value, business_segments)
            if segment is None or segment["id"] in selected_segment_ids:
                continue
            selected_segments.append(segment)
            selected_segment_ids.add(segment["id"])
        selected_segment = selected_segments[0] if selected_segments else None
        with session_scope() as session:
            duplicate = _counterparty_duplicate(
                session,
                wid,
                counterparty_id=client_id,
                name=name,
                phone=phone,
                email=email,
                tax_id=tax_id,
                pinfl=pinfl,
            )
            if duplicate:
                message = _counterparty_duplicate_message(duplicate)
                if wants_json:
                    return JSONResponse({"ok": False, "error": message}, status_code=409)
                target = "client-edit" if client_id else "client-create"
                return RedirectResponse(
                    url="/clients?error=" + quote(message) + f"#{target}",
                    status_code=302,
                )
        uploaded_photo_url = await _save_client_photo_upload(wid, form.get("photo_file"))
        with session_scope() as session:
            client_type = str(form.get("client_type") or "company").strip()
            if client_type not in {"company", "individual"}:
                client_type = "company"
            status = str(form.get("status") or "active").strip()
            if status not in {"active", "inactive"}:
                status = "active"
            crm_status = str(form.get("crm_status") or "new_lead").strip()
            if crm_status not in CLIENT_CRM_STATUS_LABELS:
                crm_status = "new_lead"
            industry = str(form.get("industry") or "").strip()
            map_icon = str(form.get("map_icon") or "").strip()
            if selected_segment is not None:
                industry = selected_segment["name"]
                map_icon = selected_segment["icon"]
            if not map_icon or map_icon == "default":
                map_icon = industry or "default"
            selected_programs: list[str] = []
            for value in form.getlist("programs"):
                program = str(value or "").strip()
                if program and program not in selected_programs:
                    selected_programs.append(program)
            custom_program = str(form.get("program_custom") or form.get("program") or "").strip()
            if custom_program and custom_program not in selected_programs:
                selected_programs.append(custom_program)
            address = str(form.get("address") or "").strip()
            latitude = _clean_client_coordinate(form.get("latitude"), minimum=-90, maximum=90)
            longitude = _clean_client_coordinate(form.get("longitude"), minimum=-180, maximum=180)
            if address and (not latitude or not longitude):
                geocoded_latitude, geocoded_longitude = _geocode_client_address(address)
                latitude = latitude or geocoded_latitude
                longitude = longitude or geocoded_longitude
            saved_row = _ensure_counterparty(
                session,
                wid,
                counterparty_id=client_id,
                name=name,
                role="both" if is_supplier else "client",
                phone=phone,
                tax_id=tax_id,
                data={
                    "official_name": str(form.get("official_name") or "").strip(),
                    "legal_name": str(form.get("legal_name") or form.get("official_name") or name).strip(),
                    "legal_address": str(form.get("legal_address") or "").strip(),
                    "photo_url": uploaded_photo_url or str(form.get("photo_url") or "").strip(),
                    "client_type": client_type,
                    "inn": tax_id,
                    "pinfl": pinfl,
                    "okved": str(form.get("okved") or "").strip(),
                    "territory": str(form.get("territory") or "").strip(),
                    "category": str(form.get("category") or "").strip(),
                    "industry": industry,
                    "map_icon": map_icon,
                    "business_segment_id": selected_segment["id"] if selected_segment else "",
                    "business_segment": selected_segment["name"] if selected_segment else "",
                    "business_segment_icon": selected_segment["icon"] if selected_segment else "",
                    "business_segment_ids": [segment["id"] for segment in selected_segments],
                    "business_segments": [dict(segment) for segment in selected_segments],
                    "program": ", ".join(selected_programs),
                    "programs": selected_programs,
                    "route": str(form.get("route") or "").strip(),
                    "status": status,
                    "crm_status": crm_status,
                    "is_blacklisted": str(form.get("is_blacklisted") or "").strip() == "1",
                    "sort_order": str(form.get("sort_order") or "0").strip(),
                    "code": str(form.get("code") or "").strip(),
                    "telegram": str(form.get("telegram") or "").strip(),
                    "telegram_phone": str(form.get("telegram_phone") or form.get("telegram") or "").strip(),
                    "note": str(form.get("note") or "").strip(),
                    "comment": str(form.get("comment") or form.get("note") or "").strip(),
                    "email": email,
                    "address": address,
                    "latitude": latitude,
                    "longitude": longitude,
                    "price_type": str(form.get("price_type") or "").strip(),
                    "credit_limit": str(form.get("credit_limit") or "").strip(),
                    "consignment_days": str(form.get("consignment_days") or "").strip(),
                    "cashback_percent": str(form.get("cashback_percent") or "").strip(),
                    "delivery_frequency_days": str(form.get("delivery_frequency_days") or "").strip(),
                    "owner_user": str(form.get("owner_user") or "").strip(),
                    "owner_group": str(form.get("owner_group") or "").strip(),
                    "is_client": True,
                    "is_supplier": is_supplier,
                },
            )
            _sync_crm_records_for_counterparty_status(
                session,
                wid,
                saved_row,
                crm_status,
                _crm_workspace_stages(wid),
            )
            client_id = saved_row.id
            if wants_json:
                extra = _counterparty_extra(saved_row)
                client = {
                    "id": saved_row.id,
                    "name": saved_row.name,
                    "phone": saved_row.phone or "",
                    "tax_id": saved_row.tax_id or "",
                    "price_type": str(extra.get("price_type") or ""),
                    "business_segment_id": str(extra.get("business_segment_id") or ""),
                    "business_segment": str(extra.get("business_segment") or ""),
                    "business_segment_icon": str(
                        extra.get("business_segment_icon")
                        or extra.get("map_icon")
                        or ""
                    ),
                    "business_segment_ids": list(extra.get("business_segment_ids") or []),
                    "business_segments": list(extra.get("business_segments") or []),
                    "balance_kind": "zero",
                    "balance_note": "Баланс: 0",
                    "balance": "0",
                    "balance_lines": [],
                }
                return JSONResponse({"ok": True, "client": client})
        if client_id and str(form.get("return_to_card") or "").strip() == "1":
            return RedirectResponse(url=f"/clients?client={quote(client_id)}&msg=saved#client-card", status_code=302)
        return RedirectResponse(url="/clients?msg=saved#clients", status_code=302)

    @app.post("/api/clients/{counterparty_id}/location", name="client_location_save_api")
    async def client_location_save_api(request: Request, counterparty_id: str):
        tok = request.headers.get("X-CSRF-Token") or request.headers.get("x-csrf-token") or ""
        if not csrf_matches_session(request, tok):
            return JSONResponse({"ok": False, "error": "csrf"}, status_code=403)
        wid, redir = _product_workspace_owner(request)
        if redir:
            return JSONResponse({"ok": False, "error": "auth"}, status_code=401)
        assert wid is not None
        try:
            payload = await request.json()
        except Exception:
            return JSONResponse({"ok": False, "error": "json"}, status_code=400)
        if not isinstance(payload, dict):
            return JSONResponse({"ok": False, "error": "json"}, status_code=400)
        latitude = _clean_client_coordinate(payload.get("latitude"), minimum=-90, maximum=90)
        longitude = _clean_client_coordinate(payload.get("longitude"), minimum=-180, maximum=180)
        if not latitude or not longitude:
            return JSONResponse({"ok": False, "error": "coordinates"}, status_code=400)
        address = str(payload.get("address") or "").strip()
        map_icon = str(payload.get("map_icon") or "").strip()
        with session_scope() as session:
            row = session.get(Counterparty, counterparty_id)
            if not row or row.workspace_owner_id != wid:
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            has_client, _has_supplier = _counterparty_role_flags(row.kind)
            if not has_client:
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            extra = _counterparty_extra(row)
            extra["latitude"] = latitude
            extra["longitude"] = longitude
            if address:
                extra["address"] = address
            if map_icon:
                extra["map_icon"] = map_icon
            row.data = extra
            flag_modified(row, "data")
        return JSONResponse(
            {
                "ok": True,
                "latitude": latitude,
                "longitude": longitude,
                "address": address,
                "map_icon": map_icon,
            }
        )

    @app.post("/api/clients/{counterparty_id}/segments", name="client_segments_save_api")
    async def client_segments_save_api(request: Request, counterparty_id: str):
        token = request.headers.get("X-CSRF-Token") or request.headers.get("x-csrf-token") or ""
        if not csrf_matches_session(request, token):
            return JSONResponse({"ok": False, "error": "csrf"}, status_code=403)
        wid, redir = _product_workspace_owner(request)
        if redir:
            return JSONResponse({"ok": False, "error": "auth"}, status_code=401)
        assert wid is not None
        try:
            payload = await request.json()
        except Exception:
            return JSONResponse({"ok": False, "error": "json"}, status_code=400)
        raw_segment_ids = payload.get("segment_ids") if isinstance(payload, dict) else None
        if not isinstance(raw_segment_ids, list):
            return JSONResponse({"ok": False, "error": "segment_ids"}, status_code=400)

        configured_segments = _workspace_business_segments(wid)
        configured_by_id = {segment["id"]: segment for segment in configured_segments}
        selected_segments: list[dict[str, str]] = []
        selected_ids: set[str] = set()
        for raw_segment_id in raw_segment_ids:
            segment_id = str(raw_segment_id or "").strip()
            segment = configured_by_id.get(segment_id)
            if segment is None or segment_id in selected_ids:
                continue
            selected_segments.append(dict(segment))
            selected_ids.add(segment_id)

        with session_scope() as session:
            row = session.get(Counterparty, counterparty_id)
            if not row or row.workspace_owner_id != wid:
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            has_client, _has_supplier = _counterparty_role_flags(row.kind)
            if not has_client:
                return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
            extra = _counterparty_extra(row)
            selected_segment = selected_segments[0] if selected_segments else None
            extra["business_segment_ids"] = [segment["id"] for segment in selected_segments]
            extra["business_segments"] = selected_segments
            extra["business_segment_id"] = selected_segment["id"] if selected_segment else ""
            extra["business_segment"] = selected_segment["name"] if selected_segment else ""
            extra["business_segment_icon"] = selected_segment["icon"] if selected_segment else ""
            extra["industry"] = selected_segment["name"] if selected_segment else ""
            extra["map_icon"] = selected_segment["icon"] if selected_segment else "default"
            row.data = extra
            flag_modified(row, "data")

        return JSONResponse({"ok": True, "segments": selected_segments})

