    @app.post("/telephony/contacts/confirm", name="telephony_contact_confirm")
    async def telephony_contact_confirm(request: Request):
        form = await request.form()
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            return RedirectResponse(url="/telephony?err=csrf#numbers", status_code=302)
        wid, redir = _product_workspace_owner(request)
        if redir:
            return redir
        assert wid is not None
        contact_id = str(form.get("contact_id") or "").strip()
        name = str(form.get("name") or "").strip()
        phone = str(form.get("phone") or "").strip()
        if not contact_id or not name or len(_telephony_normalized_phone(phone)) < 7:
            return RedirectResponse(
                url="/telephony?error=" + quote("Укажите имя и корректный номер телефона") + "#numbers",
                status_code=302,
            )
        previous_name = ""
        previous_phone = ""
        with session_scope() as session:
            row = session.get(Counterparty, contact_id)
            if not row or row.workspace_owner_id != wid or row.kind not in {"client", "both"}:
                return RedirectResponse(
                    url="/telephony?error=" + quote("Контакт не найден") + "#numbers",
                    status_code=302,
                )
            candidates = session.execute(
                select(Counterparty).where(
                    Counterparty.workspace_owner_id == wid,
                    Counterparty.id != row.id,
                )
            ).scalars().all()
            if any(
                _telephony_phone_matches(phone, candidate.phone or _counterparty_extra(candidate).get("phone"))
                for candidate in candidates
            ):
                return RedirectResponse(
                    url="/telephony?error=" + quote("Этот номер уже сохранен у другого контакта") + "#numbers",
                    status_code=302,
                )
            previous_name = str(row.name or "").strip()
            previous_phone = str(row.phone or _counterparty_extra(row).get("phone") or "").strip()
            row.name = name[:255]
            row.phone = phone[:64]
            extra = _counterparty_extra(row)
            extra.update(
                {
                    "phone": phone,
                    "is_client": True,
                    "telephony_confirmed": True,
                    "telephony_confirmed_at": datetime.now(timezone.utc).isoformat(),
                    "telephony_confirmed_by": _telephony_user_name(request),
                }
            )
            row.data = extra
            flag_modified(row, "data")

        data = _telephony_settings_payload(wid)
        stored_calls = data.get("telephony_calls") if isinstance(data.get("telephony_calls"), list) else []
        changed = False
        for call in stored_calls:
            if not isinstance(call, dict):
                continue
            call_phone = str(call.get("phone") or "").strip()
            call_client = str(call.get("client") or "").strip()
            if (previous_phone and _telephony_phone_matches(previous_phone, call_phone)) or (
                previous_name and call_client.casefold() == previous_name.casefold()
            ):
                call["client"] = name
                call["phone"] = phone
                changed = True
        if changed:
            data["telephony_calls"] = stored_calls
            save_workspace_settings(wid, data)
        return RedirectResponse(url="/telephony?msg=saved#numbers", status_code=302)

    @app.post("/telephony/contacts/delete", name="telephony_contacts_delete")
    async def telephony_contacts_delete(request: Request):
        form = await request.form()
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            return RedirectResponse(url="/telephony?err=csrf#numbers", status_code=302)
        wid, redir = _product_workspace_owner(request)
        if redir:
            return redir
        assert wid is not None
        contact_ids = list(
            dict.fromkeys(
                str(value or "").strip()
                for value in form.getlist("contact_ids")
                if str(value or "").strip()
            )
        )[:2000]
        if not contact_ids:
            return RedirectResponse(
                url="/telephony?error=" + quote("Выберите хотя бы один контакт") + "#numbers",
                status_code=302,
            )

        deleted_at = datetime.now(timezone.utc).isoformat()
        deleted_by = _telephony_user_name(request)
        deleted_rows: list[dict[str, Any]] = []
        with session_scope() as session:
            rows = session.execute(
                select(Counterparty).where(
                    Counterparty.workspace_owner_id == wid,
                    Counterparty.kind.in_(["client", "both"]),
                    Counterparty.id.in_(contact_ids),
                )
            ).scalars().all()
            for row in rows:
                extra = _counterparty_extra(row)
                phone = str(row.phone or extra.get("phone") or "").strip()
                normalized_phone = _telephony_normalized_phone(phone)
                external_id = f"phone:{normalized_phone}" if normalized_phone else f"contact:{row.id}"
                extra.update(
                    {
                        "telephony_deleted": True,
                        "telephony_deleted_at": deleted_at,
                        "telephony_deleted_by": deleted_by,
                    }
                )
                row.data = extra
                flag_modified(row, "data")
                deleted_rows.append(
                    {
                        "contact_id": str(row.id),
                        "external_id": external_id,
                        "phone": phone,
                        "name": str(row.name or "").strip(),
                        "deleted_at": deleted_at,
                        "deleted_by": deleted_by,
                    }
                )

        if not deleted_rows:
            return RedirectResponse(
                url="/telephony?error=" + quote("Выбранные контакты не найдены") + "#numbers",
                status_code=302,
            )

        data = _telephony_settings_payload(wid)
        existing_rows = data.get("telephony_deleted_contacts")
        merged: dict[str, dict[str, Any]] = {}
        if isinstance(existing_rows, list):
            for item in existing_rows:
                if not isinstance(item, dict):
                    continue
                key = str(item.get("external_id") or item.get("contact_id") or "").strip()
                if key:
                    merged[key] = dict(item)
        for item in deleted_rows:
            merged[str(item["external_id"])] = item
        data["telephony_deleted_contacts"] = list(merged.values())[-5000:]
        save_workspace_settings(wid, data)
        return RedirectResponse(url="/telephony?msg=deleted#numbers", status_code=302)

    @app.post("/telephony/providers/password", name="telephony_provider_password")
    async def telephony_provider_password(request: Request):
        form = await request.form()
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            return JSONResponse({"ok": False, "error": "csrf"}, status_code=403)
        wid, redir = _product_workspace_owner(request)
        if redir or not valid_workspace_owner_id(wid):
            return JSONResponse({"ok": False, "error": "login_required"}, status_code=401)
        provider_id = str(form.get("provider_id") or "").strip()
        data = _telephony_settings_payload(str(wid))
        provider = next(
            (
                item
                for item in (data.get("telephony_providers") or [])
                if isinstance(item, dict) and str(item.get("id") or "").strip() == provider_id
            ),
            None,
        )
        if provider is None:
            return JSONResponse({"ok": False, "error": "not_found"}, status_code=404)
        response = JSONResponse({"ok": True, "password": str(provider.get("password") or "")})
        response.headers["Cache-Control"] = "no-store, max-age=0"
        response.headers["Pragma"] = "no-cache"
        return response

    @app.post("/telephony/providers/device/unbind", name="telephony_provider_device_unbind")
    async def telephony_provider_device_unbind(request: Request):
        form = await request.form()
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            return RedirectResponse(url="/telephony?err=csrf#integrations", status_code=302)
        wid, redir = _product_workspace_owner(request)
        if redir:
            return redir
        assert wid is not None
        provider_id = str(form.get("provider_id") or "").strip()
        device_id = str(form.get("device_id") or "").strip()
        if not provider_id or not device_id:
            return RedirectResponse(
                url="/telephony?error=" + quote("Не удалось определить SIP-линию или устройство") + "#integrations",
                status_code=302,
            )

        data = _telephony_settings_payload(wid)
        providers = data.get("telephony_providers") if isinstance(data.get("telephony_providers"), list) else []
        provider = next(
            (
                item
                for item in providers
                if isinstance(item, dict) and str(item.get("id") or "").strip() == provider_id
            ),
            None,
        )
        if provider is None:
            return RedirectResponse(
                url="/telephony?error=" + quote("SIP-линия не найдена") + "#integrations",
                status_code=302,
            )

        sessions = data.get("telephony_softphone_sessions")
        if isinstance(sessions, dict):
            remaining_sessions = {
                key: value
                for key, value in sessions.items()
                if not (
                    isinstance(value, dict)
                    and str(value.get("provider_id") or "").strip() == provider_id
                    and str(value.get("device_id") or key).strip() == device_id
                )
            }
            data["telephony_softphone_sessions"] = remaining_sessions
        else:
            remaining_sessions = {}
        legacy_auth = data.get("telephony_softphone_auth")
        if isinstance(legacy_auth, dict) and (
            str(legacy_auth.get("provider_id") or "").strip() == provider_id
            and str(legacy_auth.get("device_id") or "").strip() == device_id
        ):
            data.pop("telephony_softphone_auth", None)

        devices = data.get("telephony_devices") if isinstance(data.get("telephony_devices"), list) else []
        data["telephony_devices"] = [
            item
            for item in devices
            if not (
                isinstance(item, dict)
                and device_id
                in {
                    str(item.get("device_id") or "").strip(),
                    str(item.get("id") or "").strip().removeprefix("upos-sip:"),
                }
            )
        ]
        revoked = data.get("telephony_revoked_devices")
        if not isinstance(revoked, dict):
            revoked = {}
        revoked[device_id] = {
            "provider_id": provider_id,
            "revoked_at": datetime.now(timezone.utc).isoformat(),
        }
        data["telephony_revoked_devices"] = dict(list(revoked.items())[-200:])

        provider_still_bound = any(
            isinstance(value, dict) and str(value.get("provider_id") or "").strip() == provider_id
            for value in remaining_sessions.values()
        )
        if not provider_still_bound:
            provider["status"] = "offline"
            provider["last_disconnected_at"] = datetime.now(timezone.utc).isoformat()
            provider["last_test_message"] = "Устройство отвязано от SIP-линии"
            for key in (
                "last_connected_at",
                "last_connected_device_id",
                "last_connected_device_name",
                "last_connected_user",
            ):
                provider.pop(key, None)
        data["telephony_providers"] = providers
        save_workspace_settings(wid, data)
        return RedirectResponse(url="/telephony?msg=device_unbound#integrations", status_code=302)

    @app.post("/telephony/providers/save", name="telephony_provider_save")
    async def telephony_provider_save(request: Request):
        form = await request.form()
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            return RedirectResponse(url="/telephony?err=csrf#integrations", status_code=302)
        wid, redir = _product_workspace_owner(request)
        if redir:
            return redir
        assert wid is not None
        provider_id = str(form.get("provider_id") or "").strip()
        name = str(form.get("name") or "").strip()
        raw_host = str(form.get("host") or "").strip()
        host, port, endpoint = _telephony_parse_sip_host(raw_host, form.get("port") or "5060")
        login = str(form.get("login") or "").strip()
        if not name or not host or not login:
            return RedirectResponse(url="/telephony?error=" + quote("Название, SIP-сервер и логин обязательны") + "#integrations", status_code=302)
        data = _telephony_settings_payload(wid)
        providers = data.get("telephony_providers") if isinstance(data.get("telephony_providers"), list) else []
        existing_index = next(
            (index for index, item in enumerate(providers) if str(item.get("id") or "") == provider_id),
            None,
        )
        existing = dict(providers[existing_index]) if existing_index is not None else {}
        password = str(form.get("password") or "").strip() or str(existing.get("password") or "").strip()
        if not password:
            return RedirectResponse(url="/telephony?error=" + quote("Пароль SIP-аккаунта обязателен") + "#integrations", status_code=302)

        updated = {
            **existing,
            "id": provider_id or str(uuid.uuid4()),
            "name": name,
            "kind": "SIP",
            "host": host,
            "port": str(port),
            "endpoint": endpoint,
            "login": login,
            "account": login,
            "password": password,
            "codec": str(form.get("codec") or "G711").strip(),
            "transport": str(form.get("transport") or "UDP").strip().upper(),
            # WebSocket-адрес для звонков из браузера (софтфон в PWA). Обычный
            # SIP по UDP/TCP браузер не умеет, поэтому нужен wss://host:port/ws.
            "ws_url": str(form.get("ws_url") or "").strip(),
            "employee": str(form.get("employee") or "").strip(),
            "note": str(form.get("note") or "").strip(),
            "created_at": existing.get("created_at") or datetime.now(timezone.utc).isoformat(),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }
        connection_fields = ("host", "port", "login", "password", "transport")
        connection_changed = not existing or any(
            str(existing.get(key) or "") != str(updated.get(key) or "") for key in connection_fields
        )
        if connection_changed:
            updated["status"] = "draft"
            for key in (
                "last_connected_at",
                "last_connected_device_id",
                "last_connected_device_name",
                "last_connected_user",
            ):
                updated.pop(key, None)
        if existing_index is None:
            providers.insert(0, updated)
        else:
            providers[existing_index] = updated
        data["telephony_providers"] = providers[:500]
        save_workspace_settings(wid, data)
        return RedirectResponse(url="/telephony?msg=saved#integrations", status_code=302)

    @app.post("/telephony/providers/test", name="telephony_provider_test")
    async def telephony_provider_test(request: Request):
        form = await request.form()
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            return RedirectResponse(url="/telephony?err=csrf#integrations", status_code=302)
        wid, redir = _product_workspace_owner(request)
        if redir:
            return redir
        assert wid is not None
        status_value, message = _telephony_update_provider_test(wid, str(form.get("provider_id") or ""))
        key = "saved" if status_value in {"online", "testing"} else "sip_test_failed"
        return RedirectResponse(url=f"/telephony?msg={quote(key)}&note={quote(message)}#integrations", status_code=302)

    @app.api_route("/api/telephony/calls/ingest", methods=["GET", "POST"], name="telephony_calls_ingest_api")
    async def telephony_calls_ingest_api(request: Request):
        payload: dict[str, Any] = {key: value for key, value in request.query_params.items()}
        recording_upload = None
        if request.method == "POST":
            content_type = str(request.headers.get("content-type") or "").lower()
            try:
                if "application/json" in content_type:
                    body = await request.json()
                    if isinstance(body, dict):
                        payload.update(body)
                else:
                    form = await request.form()
                    form_payload, recording_upload = _telephony_recording_upload_from_form(form)
                    payload.update(form_payload)
            except Exception:
                logger.exception("[telephony] failed to parse webhook payload")

        wid = str(_telephony_first(payload, "workspace_owner_id", "workspace_id", "owner_id", "account_id")).strip()
        if not valid_workspace_owner_id(wid):
            wid = _telephony_default_workspace_owner_id()
        if not valid_workspace_owner_id(wid):
            return JSONResponse({"ok": False, "error": "workspace_required"}, status_code=400)

        provided_token = _telephony_request_token(payload, request)
        if not _telephony_token_allowed(wid, provided_token):
            return JSONResponse({"ok": False, "error": "bad_token"}, status_code=401)
        integration_data = _telephony_settings_payload(wid)
        if _telephony_device_is_revoked(integration_data, payload):
            return JSONResponse({"ok": False, "error": "device_unbound"}, status_code=401)

        event = str(payload.get("event") or "").strip().lower()
        if event == "test":
            return JSONResponse({"ok": True, "workspace_owner_id": wid, "message": "connected"})
        if event in {"contacts", "contacts_sync", "sync_contacts", "contact_created", "contact_updated"}:
            result = _telephony_sync_contacts(wid, payload)
            return JSONResponse({"ok": True, "workspace_owner_id": wid, **result})
        if event in {"logout", "disconnect", "offline"}:
            data = _telephony_settings_payload(wid)
            device_id = str(payload.get("device_id") or "").strip()
            provider_id = str(_telephony_first(payload, "provider_id", "sip_provider_id")).strip()
            providers = data.get("telephony_providers") if isinstance(data.get("telephony_providers"), list) else []
            for provider in providers:
                if not isinstance(provider, dict) or str(provider.get("id") or "").strip() != provider_id:
                    continue
                connected_device_id = str(provider.get("last_connected_device_id") or "").strip()
                if connected_device_id and device_id and connected_device_id != device_id:
                    continue
                provider["status"] = "offline"
                provider["last_disconnected_at"] = datetime.now(timezone.utc).isoformat()
                provider["last_test_message"] = "U-POS Sip вышел из аккаунта"
            sessions = data.get("telephony_softphone_sessions")
            if isinstance(sessions, dict) and device_id:
                sessions.pop(device_id, None)
                data["telephony_softphone_sessions"] = sessions
            legacy_auth = data.get("telephony_softphone_auth")
            if isinstance(legacy_auth, dict) and (
                not device_id or str(legacy_auth.get("device_id") or "").strip() == device_id
            ):
                data.pop("telephony_softphone_auth", None)
            data["telephony_providers"] = providers
            save_workspace_settings(wid, data)
            return JSONResponse(
                {
                    "ok": True,
                    "workspace_owner_id": wid,
                    "provider_id": provider_id,
                    "connected": False,
                }
            )
        if event in {"heartbeat", "device_heartbeat", "ping"}:
            data = integration_data
            now_iso = datetime.now(timezone.utc).isoformat()
            device = _telephony_upsert_device_entry(data, payload, now_iso)
            provider = _telephony_mark_provider_connection(data, payload, now_iso, device)
            save_workspace_settings(wid, data)
            contacts_result = _telephony_sync_contacts(wid, payload) if payload.get("contacts") else None
            return JSONResponse(
                {
                    "ok": True,
                    "workspace_owner_id": wid,
                    "device": device,
                    "provider_id": str((provider or {}).get("id") or ""),
                    "connected": bool(provider),
                    "contacts": contacts_result,
                }
            )

        if recording_upload is not None or _telephony_first(
            payload,
            "recording_base64",
            "audio_base64",
            "file_base64",
            "record_base64",
        ):
            recording_url, recording_error, error_status, recording_size = await _telephony_store_recording_upload(
                wid,
                payload,
                recording_upload,
            )
            if recording_error:
                logger.warning(
                    "[telephony] recording in call ingest rejected; workspace=%s error=%s",
                    wid,
                    recording_error,
                )
                return JSONResponse({"ok": False, "error": recording_error}, status_code=error_status)
            payload["recording_url"] = recording_url
            payload["recording_path"] = recording_url
            payload["event"] = str(payload.get("event") or "recording")
            logger.info(
                "[telephony] recording received with call event; workspace=%s call=%s bytes=%s",
                wid,
                _telephony_call_reference(_telephony_first(payload, "call_id", "id", "uuid", "call_uuid")),
                recording_size,
            )

        call_item = _telephony_upsert_call_from_payload(wid, payload)
        integration = _telephony_integration_context(request, wid, _telephony_settings_payload(wid))
        return JSONResponse(
            {
                "ok": True,
                "workspace_owner_id": wid,
                "call": call_item,
                "recording_upload_url": integration["recording_upload_url"],
                "recording_required": call_item.get("recording_state") == "pending",
            }
        )

    @app.post("/api/telephony/contacts/sync", name="telephony_contacts_sync_api")
    async def telephony_contacts_sync_api(request: Request):
        payload: dict[str, Any] = {key: value for key, value in request.query_params.items()}
        try:
            if "application/json" in str(request.headers.get("content-type") or "").lower():
                body = await request.json()
                if isinstance(body, list):
                    payload["contacts"] = body
                elif isinstance(body, dict):
                    payload.update(body)
            else:
                form = await request.form()
                payload.update({str(key): value for key, value in form.items()})
        except Exception:
            return JSONResponse({"ok": False, "error": "invalid_payload"}, status_code=400)
        wid = str(_telephony_first(payload, "workspace_owner_id", "workspace_id", "owner_id", "account_id")).strip()
        if not valid_workspace_owner_id(wid):
            wid = _telephony_default_workspace_owner_id()
        if not valid_workspace_owner_id(wid):
            return JSONResponse({"ok": False, "error": "workspace_required"}, status_code=400)
        if not _telephony_token_allowed(wid, _telephony_request_token(payload, request)):
            return JSONResponse({"ok": False, "error": "bad_token"}, status_code=401)
        if _telephony_device_is_revoked(_telephony_settings_payload(wid), payload):
            return JSONResponse({"ok": False, "error": "device_unbound"}, status_code=401)
        result = _telephony_sync_contacts(wid, payload)
        return JSONResponse({"ok": True, "workspace_owner_id": wid, **result})

    @app.post("/api/telephony/recordings/upload", name="telephony_recording_upload_api")
    async def telephony_recording_upload_api(request: Request):
        payload: dict[str, Any] = {key: value for key, value in request.query_params.items()}
        upload = None
        try:
            if "application/json" in str(request.headers.get("content-type") or "").lower():
                body = await request.json()
                if not isinstance(body, dict):
                    raise ValueError("invalid json payload")
                payload.update(body)
            else:
                form = await request.form()
                form_payload, upload = _telephony_recording_upload_from_form(form)
                payload.update(form_payload)
        except Exception:
            logger.exception("[telephony] failed to parse recording upload")
            return JSONResponse({"ok": False, "error": "invalid_recording_payload"}, status_code=400)
        wid = str(_telephony_first(payload, "workspace_owner_id", "workspace_id", "owner_id", "account_id")).strip()
        if not valid_workspace_owner_id(wid):
            wid = _telephony_default_workspace_owner_id()
        if not valid_workspace_owner_id(wid):
            return JSONResponse({"ok": False, "error": "workspace_required"}, status_code=400)
        if not _telephony_token_allowed(wid, _telephony_request_token(payload, request)):
            return JSONResponse({"ok": False, "error": "bad_token"}, status_code=401)
        if _telephony_device_is_revoked(_telephony_settings_payload(wid), payload):
            return JSONResponse({"ok": False, "error": "device_unbound"}, status_code=401)
        if not _telephony_first(payload, "call_id", "id", "uuid", "call_uuid", "callid", "uniqueid", "linkedid") and not _telephony_first(
            payload, "phone", "remote_ext", "caller", "caller_id", "to", "from", "src", "dst"
        ):
            return JSONResponse({"ok": False, "error": "call_reference_required"}, status_code=400)
        recording_url, recording_error, error_status, recording_size = await _telephony_store_recording_upload(
            wid,
            payload,
            upload,
        )
        if recording_error:
            logger.warning(
                "[telephony] recording upload rejected; workspace=%s error=%s",
                wid,
                recording_error,
            )
            return JSONResponse({"ok": False, "error": recording_error}, status_code=error_status)
        payload["recording_url"] = recording_url
        payload["recording_path"] = recording_url
        payload["event"] = str(payload.get("event") or "recording")
        call_item = _telephony_upsert_call_from_payload(wid, payload)
        logger.info(
            "[telephony] recording upload completed; workspace=%s call=%s bytes=%s",
            wid,
            _telephony_call_reference(call_item.get("external_id") or call_item.get("id")),
            recording_size,
        )
        return JSONResponse(
            {
                "ok": True,
                "workspace_owner_id": wid,
                "recording_url": recording_url,
                "call": call_item,
            }
        )

    @app.get("/api/telephony/config", name="telephony_softphone_config_api")
    def telephony_softphone_config_api(request: Request):
        wid = str(
            request.query_params.get("workspace_owner_id")
            or request.query_params.get("workspace_id")
            or request.headers.get("X-UPOS-Workspace")
            or ""
        ).strip()
        if not valid_workspace_owner_id(wid):
            wid = _telephony_default_workspace_owner_id()
        if not valid_workspace_owner_id(wid):
            return JSONResponse({"ok": False, "error": "workspace_required"}, status_code=400)
        provided_token = _telephony_request_token({key: value for key, value in request.query_params.items()}, request)
        if not _telephony_token_allowed(wid, provided_token):
            return JSONResponse({"ok": False, "error": "bad_token"}, status_code=401)
        data = _telephony_settings_payload(wid)
        integration = _telephony_integration_context(request, wid, data)
        provider_id = str(request.query_params.get("provider_id") or "").strip()
        return JSONResponse(
            {
                "ok": True,
                "workspace_owner_id": wid,
                "endpoint_url": integration["endpoint_url"],
                "contacts_sync_url": integration["contacts_sync_url"],
                "recording_upload_url": integration["recording_upload_url"],
                "token": integration["token"],
                "accounts": _telephony_sip_accounts_for_softphone(data, provider_id),
            }
        )

    @app.post("/api/telephony/softphone/login", name="telephony_softphone_login_api")
    async def telephony_softphone_login_api(request: Request):
        try:
            payload = await request.json()
            if not isinstance(payload, dict):
                payload = {}
        except Exception:
            form = await request.form()
            payload = {str(key): value for key, value in form.items()}

        account_id = str(payload.get("account_id") or payload.get("organization") or payload.get("workspace") or "").strip()
        login_value = str(payload.get("login") or payload.get("username") or "").strip()
        password = str(payload.get("password") or "")
        wid = _telephony_workspace_owner_for_account(account_id)
        if not valid_workspace_owner_id(wid):
            return JSONResponse({"ok": False, "error": "bad_credentials"}, status_code=401)

        data = _telephony_settings_payload(wid)
        provider = _telephony_provider_for_credentials(data, login_value, password)
        if provider is None:
            return JSONResponse({"ok": False, "error": "bad_credentials"}, status_code=401)

        integration = _telephony_integration_context(request, wid, data)
        now_iso = datetime.now(timezone.utc).isoformat()
        provider_id = str(provider.get("id") or "").strip()
        device_id = str(payload.get("device_id") or payload.get("app_instance_id") or "").strip()
        revoked = data.get("telephony_revoked_devices")
        if isinstance(revoked, dict) and device_id:
            revoked.pop(device_id, None)
            if revoked:
                data["telephony_revoked_devices"] = revoked
            else:
                data.pop("telephony_revoked_devices", None)
        auth_entry = {
            "authenticated_at": now_iso,
            "provider_id": provider_id,
            "login": str(provider.get("login") or login_value).strip(),
            "device_id": device_id,
        }
        data["telephony_softphone_auth"] = auth_entry
        sessions = data.get("telephony_softphone_sessions")
        if not isinstance(sessions, dict):
            sessions = {}
        session_key = device_id or f"provider:{provider_id}"
        sessions[session_key] = auth_entry
        data["telephony_softphone_sessions"] = dict(list(sessions.items())[-100:])
        save_workspace_settings(wid, data)
        accounts = _telephony_sip_accounts_for_softphone(data, provider_id)
        config_query = urlencode({"provider_id": provider_id})
        return JSONResponse(
            {
                "ok": True,
                "workspace_owner_id": wid,
                "endpoint_url": integration["endpoint_url"],
                "contacts_sync_url": integration["contacts_sync_url"],
                "recording_upload_url": integration["recording_upload_url"],
                "config_url": f"{_telephony_public_base_url(request)}/api/telephony/config?{config_query}",
                "token": integration["token"],
                "token_header": integration["token_header"],
                "user": {
                    "id": provider_id,
                    "login": str(provider.get("login") or login_value),
                    "name": str(provider.get("employee") or provider.get("name") or login_value),
                    "role": "sip",
                },
                "provider_id": provider_id,
                "connected": telephony_provider_is_connected(provider),
                "accounts": accounts,
            }
        )

    @app.get("/api/telephony/dashboard", name="telephony_dashboard_api")
    def telephony_dashboard_api(request: Request):
        wid, redir = _product_workspace_owner(request)
        if redir:
            return JSONResponse({"ok": False, "error": "login_required"}, status_code=401)
        assert wid is not None
        return JSONResponse({"ok": True, "dashboard": telephony_account_dashboard(wid)})

    @app.post("/api/telephony/incoming-call", name="telephony_incoming_call_api")
    async def telephony_incoming_call_api(request: Request):
        try:
            payload = await request.json()
        except Exception:
            payload = {}
        user = request.session.get("user") or {}
        wid = str(payload.get("workspace_owner_id") or user.get("workspace_owner_id") or user.get("user_id") or "").strip()
        if not valid_workspace_owner_id(wid):
            return JSONResponse({"ok": False, "error": "workspace_required"}, status_code=401)
        raw_phone = str(payload.get("phone") or payload.get("from") or payload.get("caller") or "").strip()
        clean_phone = re.sub(r"\D+", "", raw_phone)
        client_name = str(payload.get("client") or "").strip()
        synced_client = _telephony_upsert_web_client(wid, payload, phone=raw_phone, name=client_name)
        if synced_client:
            client_name = str(synced_client.get("name") or client_name).strip()
        with session_scope() as session:
            if not client_name and clean_phone:
                clients = session.execute(
                    select(Counterparty)
                    .where(Counterparty.workspace_owner_id == wid)
                    .order_by(Counterparty.updated_at.desc())
                ).scalars().all()
                for client in clients:
                    extra = _counterparty_extra(client)
                    client_phone = re.sub(r"\D+", "", str(client.phone or extra.get("phone") or ""))
                    if client_phone and clean_phone.endswith(client_phone[-9:]):
                        client_name = client.name
                        break
        call_item = {
            "client": client_name or "Неизвестный клиент",
            "phone": raw_phone,
            "direction": "incoming",
            "started_at": str(payload.get("started_at") or datetime.now(timezone.utc).isoformat()[:16]),
            "responsible": str(payload.get("responsible") or "").strip(),
            "status": str(payload.get("status") or "missed").strip() or "missed",
            "note": str(payload.get("note") or "Входящий webhook").strip(),
            "source": "webhook",
        }
        _telephony_save_item(wid, "telephony_calls", call_item)
        call_item["direction_label"] = _telephony_direction_label(call_item["direction"])
        call_item["status_label"] = _telephony_status_label("call", call_item["status"])
        return JSONResponse({"ok": True, "call": call_item, "client": client_name})

    @app.get("/messengers", response_class=HTMLResponse, name="messengers_get")
    def messengers_get(
        request: Request,
        q: str = "",
        channel: str = "",
        responsible: str = "",
        status: str = "all",
    ):
        module_redirect = _employee_module_redirect(request, "messengers")
        if module_redirect is not None:
            return module_redirect
        wid, redir = _product_workspace_owner(request)
        if redir:
            return redir
        assert wid is not None
        filters = {
            "q": q.strip(),
            "channel": channel.strip() or "Telegram",
            "responsible": responsible.strip(),
            "status": status.strip() or "all",
        }
        user = request.session.get("user") or {}
        channel_options = ["Telegram", "Instagram", "WhatsApp", "Facebook", "Сайт"]
        responsible_options = sorted({str(user.get("name") or "").strip()} - {""})
        data = _messenger_settings_payload(wid)
        all_threads = _messenger_threads_from_sources(wid)
        channel_message_counts: dict[str, int] = {}
        for item in all_threads:
            key = _messenger_channel_key(str(item.get("channel") or ""))
            message_count = len(item.get("messages") or [])
            if key:
                channel_message_counts[key] = channel_message_counts.get(key, 0) + message_count
        threads = _messenger_filter_rows(all_threads, filters)
        campaigns = _messenger_filter_rows(
            [dict(row, status_label=_messenger_status_label(str(row.get("status") or ""))) for row in data.get("messenger_campaigns") or []],
            filters,
        )
        templates_rows = _messenger_filter_rows(
            [dict(row, status_label=_messenger_status_label(str(row.get("status") or "active"))) for row in data.get("messenger_templates") or []],
            filters,
        )
        auto_reply = data.get("messenger_auto_reply") if isinstance(data.get("messenger_auto_reply"), dict) else {}
        threads_json = json.dumps(threads, ensure_ascii=False, default=str).replace("</", "<\\/")
        templates_json = json.dumps(templates_rows, ensure_ascii=False, default=str).replace("</", "<\\/")
        return tpl(
            request,
            "home_business_module.html",
            variant="user",
            active="messengers",
            module=_business_module_context("messengers"),
            messenger_filters=filters,
            messenger_options={
                "channels": channel_options,
                "responsibles": responsible_options,
                "clients": _messenger_client_options(wid),
            },
            messenger_channel_message_counts=channel_message_counts,
            messenger_threads=threads,
            messenger_threads_json=threads_json,
            messenger_campaigns=campaigns,
            messenger_templates=templates_rows,
            messenger_templates_json=templates_json,
            messenger_auto_reply=auto_reply,
            flash_ok=request.query_params.get("msg"),
            flash_err=_module_flash_error(request),
        )

