    @app.post("/earnings/rules", name="earnings_rules_save")
    async def earnings_rules_save(request: Request):
        oid, redir = _current_org_html_owner(request)
        if redir:
            return redir
        assert oid is not None
        form = await request.form()
        if not csrf_matches_session(request, str(form.get("csrf_token") or "")):
            return RedirectResponse(url="/earnings?error=csrf", status_code=302)
        _wid, own_only = _earnings_scope(request)
        if own_only:
            return RedirectResponse(url="/earnings?error=" + quote("Недостаточно прав"), status_code=302)
        by_user: dict[str, Any] = {}
        by_service: dict[str, Any] = {}
        for key in form.keys():
            if key.startswith("rate_value__"):
                user_id = key[len("rate_value__"):]
                raw_value = str(form.get(key) or "").strip()
                if raw_value:
                    by_user[user_id] = {
                        "type": str(form.get(f"rate_type__{user_id}") or "percent"),
                        "value": raw_value,
                    }
            elif key.startswith("service_rate__"):
                product_id = key[len("service_rate__"):]
                raw_value = str(form.get(key) or "").strip()
                if raw_value:
                    by_service[product_id] = raw_value
        save_earning_rules(
            oid,
            {"type": str(form.get("default_rate_type") or "percent"), "value": form.get("default_rate_value")},
            by_user,
            by_service,
        )
        return RedirectResponse(url="/earnings?msg=" + quote("Ставки сохранены"), status_code=302)

    def _sync_program_employees_to_hr(workspace_owner_id: str) -> None:
        """Сотрудники, заведённые в программе, автоматически появляются в HR.

        Совпадение ищем по набору слов имени, чтобы «Иванов Иван» и
        «Иван Иванов» не задваивались.
        """
        try:
            existing = {
                frozenset(str(emp.get("full_name") or "").lower().split())
                for emp in list_hr_employees(workspace_owner_id)
            }
            for emp in list_employees_safe(workspace_owner_id):
                name = str(emp.get("name") or emp.get("username") or "").strip()
                if not name:
                    continue
                key = frozenset(name.lower().split())
                if key in existing:
                    continue
                parts = name.split()
                create_hr_employee(
                    workspace_owner_id,
                    {
                        "first_name": parts[0],
                        "last_name": " ".join(parts[1:]),
                        "position": str(emp.get("position") or emp.get("employee_role_name") or ""),
                    },
                )
                existing.add(key)
        except Exception:
            logger.exception("[upos] sync program employees to HR failed")

